insert into public.equipment (id, name, category, summary, overview, model_asset, default_camera_orbit, model_credit, layout, published)
values ('digital_multimeter', 'Digital Multimeter', 'Measurement', 'Handheld meter for measuring voltage, current and resistance, and testing continuity.', 'A digital multimeter (DMM) combines a voltmeter, ammeter and ohmmeter in one handheld instrument. A rotary selector picks the function and the red and black test leads plug into jacks on the lower face. The result appears on an LCD. Always match the function, range and jack to the measurement, and respect the meter''s CAT rating.', 'models/digital_multimeter.glb', '0deg 75deg 0.45m', null, '{"units":"m","body":{"width":0.09,"height":0.18,"depth":0.045,"cornerRadius":0.008,"color":"#D9D7D2"},"parts":[{"id":"lcd_display","type":"screen","face":"front","position":[0,0.062],"size":[0.07,0.04,0.003],"color":"#9FB3A5"},{"id":"hold_button","type":"button","face":"front","position":[-0.027,0.028],"size":[0.02,0.01,0.004],"color":"#8C8B87"},{"id":"range_button","type":"button","face":"front","position":[0,0.028],"size":[0.02,0.01,0.004],"color":"#8C8B87"},{"id":"select_button","type":"button","face":"front","position":[0.027,0.028],"size":[0.02,0.01,0.004],"color":"#C9A64B"},{"id":"rotary_selector","type":"knob","face":"front","position":[0,-0.024],"size":[0.05,0.05,0.012],"color":"#4A4A48"},{"id":"ten_amp_jack","type":"port","face":"front","position":[-0.027,-0.071],"size":[0.012,0.012,0.005],"color":"#2B2B2B"},{"id":"vohm_ma_jack","type":"port","face":"front","position":[0,-0.071],"size":[0.012,0.012,0.005],"color":"#2B2B2B"},{"id":"com_jack","type":"port","face":"front","position":[0.027,-0.071],"size":[0.012,0.012,0.005],"color":"#2B2B2B"},{"id":"rubber_holster","type":"handle","face":"back","position":[0,0],"size":[0.072,0.162,0.003],"color":"#C9A64B"},{"id":"test_probes","type":"probe","face":"right","position":[0,-0.04],"size":[0.006,0.006,0.045],"color":"#A34A4A"}]}'::jsonb, true)
