insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('digital_multimeter', 'lcd_display', 1, 'LCD Display', 'Shows the measured value, its unit, the polarity sign and status symbols such as HOLD, low battery and OL (overload / out of range).', 'Read the digits together with the unit and the range shown. A leading minus sign means the leads are connected with reverse polarity. OL means the input is above the selected range or the circuit is open.', array['If the display is blank or flickers, do not trust earlier readings; check the battery before measuring a live circuit.']::text[], 'lcd_display')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('digital_multimeter', 'rotary_selector', 2, 'Rotary Function Selector', 'Selects the measurement function: AC or DC voltage, resistance, continuity, diode test, capacitance, and current ranges. It also turns the meter off.', 'Turn the dial so the pointer lines up with the function you need before connecting the probes to the circuit. Set it to OFF when finished.', array['Never turn the selector while the probes are connected to a live circuit.', 'Select the function first, then connect; a wrong setting such as current mode on a voltage source can cause a short circuit.']::text[], 'rotary_selector')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('digital_multimeter', 'com_jack', 3, 'COM Jack', 'Common (negative) input. The black test lead stays here for every measurement.', 'Plug the black lead into COM. It serves as the reference for voltage, resistance and current readings.', array['Connect the black lead first and disconnect it last when working on live circuits.']::text[], 'com_jack')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
