values ('digital_multimeter', 'vohm_ma_jack', 4, 'V/Ohm/mA Jack', 'Positive input for voltage, resistance, continuity, diode test and small current (milliamp range) measurements.', 'Plug the red lead here for voltage and resistance. Use it for mA current only when the selector is on the mA range.', array['Do not connect the leads in current mode across a voltage source such as a battery or mains outlet; this causes a short circuit and can blow the fuse or injure you.']::text[], 'vohm_ma_jack')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
