insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('digital_multimeter', 'ten_amp_jack', 5, '10A Jack', 'Positive input for large current measurements, up to the meter''s rated maximum (typically 10 A for a limited time). It is protected by a high-energy fuse.', 'Move the red lead to this jack and set the selector to the A range when the current may exceed the mA range limit. Connect the meter in series with the load.', array['Only measure current in series with the load, never across a voltage source.', 'Observe the maximum measurement time marked on the meter and never replace its fuse with a different rating.']::text[], 'ten_amp_jack')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('digital_multimeter', 'hold_button', 6, 'HOLD Button', 'Freezes the current reading on the display so it can be read after the probes are removed.', 'Press HOLD to freeze the value and press it again to release. The HOLD symbol shows on the display while active.', array['A held value does not update. Release HOLD before taking a new reading to avoid misreading an old value.']::text[], 'hold_button')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
