values ('digital_multimeter', 'range_button', 7, 'RANGE Button', 'Switches between auto-range and manual range selection.', 'Press RANGE to step through the fixed ranges, and hold it for about two seconds to return to auto-range. Use manual range for a stable reading when auto-range keeps hunting.', array['When using a manual range for an unknown voltage, start with the highest range and work down.']::text[], 'range_button')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('digital_multimeter', 'select_button', 8, 'SELECT / Backlight Button', 'Cycles through functions that share a dial position (for example DC, AC, resistance and continuity), and in many models switches the backlight on with a long press.', 'Press SELECT to change the mode shown for the dial position. Hold it for about two seconds, or follow your meter''s manual, to turn the backlight on or off.', array['Check the mode symbol on the display after pressing SELECT, before you connect the leads.']::text[], 'select_button')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
