values ('digital_multimeter', 'test_probes', 10, 'Test Probes', 'A pair of insulated leads, red (positive) and black (negative), with metal tips for touching the circuit under test.', 'Insert the plugs into the jacks, then touch the tips to the two measurement points. Keep your fingers behind the finger guards.', array['Use only leads rated at or above the CAT rating and voltage of the circuit.', 'Inspect the leads for cracks or exposed metal before every use and replace damaged ones.']::text[], 'test_probes')
