insert into public.safety_rules (equipment_id, sort_order, text) values ('digital_multimeter', 1, 'Check the meter''s CAT rating (CAT II, III or IV) and voltage rating, and only use it on circuits within those limits.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('digital_multimeter', 2, 'Never measure current by connecting the meter across a voltage source; current is measured in series with the load.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('digital_multimeter', 3, 'Inspect the meter and test leads for damage before use. Do not use a meter with cracked insulation or a damaged case.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('digital_multimeter', 4, 'Set the selector and move the lead to the correct jack before connecting to the circuit, and never change the selector while the probes are live.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('digital_multimeter', 5, 'Measure resistance, continuity and diodes only on a de-energized circuit with capacitors discharged.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('digital_multimeter', 6, 'Keep your fingers behind the probe finger guards and use one hand where possible on high voltages.');
