  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q5', 5, 'A minus sign appears before a DC voltage reading. What does it indicate?', array['The battery is flat', 'The meter is broken', 'The probes are connected with reverse polarity', 'The range is too low']::text[], 2, 'The red probe is on the more negative point. The reading is correct in magnitude; just swap probes if needed.' from public.quizzes where equipment_id = 'digital_multimeter' and slug = 'dmm_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q6', 6, 'What does the HOLD button do?', array['Locks the rotary selector', 'Freezes the current reading on the display', 'Turns the backlight on', 'Saves the value to memory']::text[], 1, 'HOLD freezes the displayed value so you can read it after removing the probes.' from public.quizzes where equipment_id = 'digital_multimeter' and slug = 'dmm_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q7', 7, 'Which meter rating is the safest choice for measuring at a building''s main distribution panel?', array['CAT III or higher, with a suitable voltage rating', 'CAT I', 'CAT II', 'No rating is needed']::text[], 0, 'Distribution panels are CAT III locations, so use a meter rated CAT III or CAT IV at the appropriate voltage.' from public.quizzes where equipment_id = 'digital_multimeter' and slug = 'dmm_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q8', 8, 'What should you do before turning the rotary selector to a different function?', array['Press HOLD', 'Switch to the 10A jack', 'Nothing, it is safe at any time', 'Disconnect the probes from the live circuit']::text[], 3, 'Never change the function while connected to a live circuit; arcing or a short can occur inside the switch.' from public.quizzes where equipment_id = 'digital_multimeter' and slug = 'dmm_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
