select id, 'q9', 9, 'Why might the meter read zero when measuring current in a working circuit?', array['The battery is too full', 'The display is too bright', 'The fuse in the current path has blown', 'The probes are too long']::text[], 2, 'A blown fuse opens the current path through the meter, so the circuit is not completed and the reading stays at zero.' from public.quizzes where equipment_id = 'digital_multimeter' and slug = 'dmm_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
