select id, 'q10', 10, 'How do you connect the probes to measure the voltage across a component?', array['In series with the component', 'In parallel across the component', 'Only to the positive terminal', 'Through the 10A jack']::text[], 1, 'Voltage is measured between two points, so the meter is connected in parallel with the component.' from public.quizzes where equipment_id = 'digital_multimeter' and slug = 'dmm_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
