-- ===== analog_multimeter =====
insert into public.equipment (id, name, category, summary, overview, model_asset, default_camera_orbit, model_credit, layout, published)
values ('analog_multimeter', 'Analog Multimeter', 'Measurement', 'Needle-type meter for measuring voltage, current and resistance, read from a printed scale.', 'An analog multimeter (multitester) shows the measured value with a pointer moving over printed scales. A large range selector chooses the function and range, and the red and black test probes plug into jacks at the bottom of the panel. Resistance ranges need a battery and must be zeroed with the ohm adjuster before use. Always start on the highest range when the value is unknown, and read the scale from straight above to avoid parallax error. Based on Sanwa YX-360TRF.', 'models/analog_multimeter.glb', '0deg 75deg 0.45m', null, '{"units":"m","body":{"width":0.1,"height":0.14,"depth":0.04,"cornerRadius":0.006,"color":"#2F3A4A"},"parts":[{"id":"meter_scale","type":"screen","face":"front","position":[0,0.035],"size":[0.082,0.052,0.003],"color":"#F2EEDC"},{"id":"mechanical_zero","type":"knob","face":"front","position":[0,-0.002],"size":[0.008,0.008,0.004],"color":"#8C8B87"},{"id":"ohm_adjust","type":"knob","face":"front","position":[-0.036,-0.012],"size":[0.012,0.012,0.008],"color":"#C9A64B"},{"id":"range_selector","type":"knob","face":"front","position":[0,-0.034],"size":[0.05,0.05,0.012],"color":"#1F1F1E"},{"id":"positive_jack","type":"port","face":"front","position":[-0.038,-0.063],"size":[0.01,0.01,0.005],"color":"#A34A4A"},{"id":"common_jack","type":"port","face":"front","position":[0.038,-0.063],"size":[0.01,0.01,0.005],"color":"#1F1F1E"},{"id":"battery_fuse_cover","type":"slot","face":"back","position":[0,0.03],"size":[0.04,0.025,0.002],"color":"#4A5568"},{"id":"tilt_stand_cover","type":"handle","face":"back","position":[0,-0.02],"size":[0.08,0.06,0.003],"color":"#C9A64B"},{"id":"test_probes","type":"probe","face":"right","position":[0,-0.03],"size":[0.006,0.006,0.045],"color":"#A34A4A"}]}'::jsonb, true)
on conflict (id) do update set name = excluded.name, category = excluded.category, summary = excluded.summary,
  overview = excluded.overview, model_asset = excluded.model_asset, default_camera_orbit = excluded.default_camera_orbit,
  model_credit = excluded.model_credit, layout = excluded.layout, published = true;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('analog_multimeter', 'meter_scale', 1, 'Meter Scale and Pointer', 'Shows the measurement as a pointer moving over several printed scales: DC/AC voltage and current, resistance (ohms), and often decibels. A mirror strip under the scale helps avoid parallax error.', 'Choose the scale that matches the selected function and range, then read the pointer with your eye directly above it so the pointer and its reflection in the mirror line up. Multiply or scale the reading as the range requires; the resistance scale reads from right (zero) to left (infinity).', array['Do not tap or shake the meter hard; the pointer movement is delicate and can be damaged by shock.']::text[], 'meter_scale')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('analog_multimeter', 'mechanical_zero', 2, 'Mechanical Zero Adjuster', 'A small screw below the pointer that sets the resting position of the pointer exactly on zero at the left end of the scale when the meter is not connected.', 'With the probes disconnected and the meter lying in its normal position, turn the screw slowly with a small screwdriver until the pointer sits exactly on the zero mark. Do this before taking voltage or current readings.', array['Disconnect the probes from any circuit before adjusting the screw, and make only small turns.']::text[], 'mechanical_zero')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('analog_multimeter', 'ohm_adjust', 3, '0 ohm Adjuster', 'Knob that compensates for battery ageing so the pointer reads exactly 0 ohm on the right end of the resistance scale when the probes are shorted together.', 'Select a resistance range, touch the two probe tips together and turn the 0 ohm knob until the pointer lies on the 0 ohm mark. Repeat after every change of resistance range.', array['If the pointer cannot reach 0 ohm, the battery is weak and should be replaced before measuring resistance.']::text[], 'ohm_adjust')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('analog_multimeter', 'range_selector', 4, 'Range Selector Switch', 'Rotary switch that selects the function (DC voltage, AC voltage, DC current, resistance) and the measuring range. It usually has an OFF position.', 'Set the pointer of the selector on the function and range you need before touching the probes to the circuit. When the value is unknown, start on the highest range and step down until the pointer gives a clear reading in the middle or upper part of the scale.', array['Never turn the selector while the probes are connected to a live circuit.', 'Never leave the selector on a resistance or current range when measuring voltage; this can damage the meter and cause injury.']::text[], 'range_selector')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('analog_multimeter', 'positive_jack', 5, 'Positive (+) Jack', 'Input jack for the red test probe, used for voltage, current and resistance measurements.', 'Plug the red probe fully into this jack. In current mode the current should enter the meter through the red probe. Note that on resistance ranges the polarity of the internal battery is reversed at the jacks, so the red jack is negative on ohm ranges.', array['Check that the probe plug is fully inserted before use; a loose plug gives unstable readings and exposes metal.']::text[], 'positive_jack')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('analog_multimeter', 'common_jack', 6, 'Common (COM / -) Jack', 'Common input jack for the black test probe, the reference for all measurements.', 'Plug the black probe into this jack for every measurement. For DC measurements, connect it to the more negative point of the circuit.', array['Connect the black probe to the circuit first and remove it last when working on live circuits.']::text[], 'common_jack')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('analog_multimeter', 'battery_fuse_cover', 7, 'Battery and Fuse Cover', 'Cover on the back that gives access to the internal batteries (needed for resistance ranges) and the protective fuse.', 'To replace a battery or fuse, set the selector to OFF, remove the probes, open the cover with a screwdriver, replace the part and close the cover firmly. Take out the battery if the meter will be stored for a long time.', array['Never open the cover with the probes connected.', 'Replace a blown fuse only with one of the exact same rating and type, and never run the meter with the cover removed.']::text[], 'battery_fuse_cover')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('analog_multimeter', 'tilt_stand_cover', 8, 'Protective Cover and Tilt Stand', 'Solid cover on the back that protects the case and can fold out as a stand to tilt the meter on the bench.', 'Use the stand to place the meter at a comfortable reading angle. Many analog meters are designed to be read in a horizontal or tilted position, so check the symbol on the scale panel.', array['Place the meter on a stable surface so it cannot fall while the probes are connected.']::text[], 'tilt_stand_cover')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('analog_multimeter', 'test_probes', 9, 'Test Probes', 'A pair of insulated leads, red (positive) and black (common), with finger guards and metal tips for touching the measurement points.', 'Insert the plugs into the jacks and touch the tips to the two measurement points. Keep your fingers behind the finger guards and keep the tips from touching each other.', array['Use only probes rated for the voltage of the circuit and inspect them for cracks before each use.', 'Replace the removable tip covers after use.']::text[], 'test_probes')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
delete from public.parts where equipment_id = 'analog_multimeter' and id not in ('meter_scale', 'mechanical_zero', 'ohm_adjust', 'range_selector', 'positive_jack', 'common_jack', 'battery_fuse_cover', 'tilt_stand_cover', 'test_probes');
delete from public.safety_rules where equipment_id = 'analog_multimeter';
insert into public.safety_rules (equipment_id, sort_order, text) values ('analog_multimeter', 1, 'Check the meter''s voltage and CAT rating and only use it on circuits within its limits. Analog meters are generally intended for low-energy circuits, so follow your meter''s manual.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('analog_multimeter', 2, 'Before use, inspect the case and test probes for cracks or exposed metal. Do not use a damaged meter.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('analog_multimeter', 3, 'Start on the highest range when the value is unknown, and never exceed the maximum input rating of the selected range.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('analog_multimeter', 4, 'Select the function and range before touching the probes to the circuit. Never turn the selector while connected to a live circuit.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('analog_multimeter', 5, 'Measure resistance only on a de-energized circuit with capacitors discharged, and never apply voltage to a resistance range.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('analog_multimeter', 6, 'Measure current only in series with the load, never across a voltage source.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('analog_multimeter', 7, 'After use, set the selector to OFF (or the highest AC voltage range) and store the meter with the probes removed.');
