insert into public.fault_scenarios (equipment_id, slug, symptom, explanation, sort_order) values ('analog_multimeter', 'pointer_wont_zero_ohms', 'On a resistance range with the probes shorted together, the pointer cannot be brought to 0 ohm using the 0 ohm adjuster.', 'The resistance ranges are powered by the internal battery. When it is weak, the adjuster no longer has enough range to reach 0 ohm and the battery must be replaced. The mechanical zero only affects the resting position, not the ohm zero.', 1)
