insert into public.fault_scenarios (equipment_id, slug, symptom, explanation, sort_order) values ('analog_multimeter', 'no_deflection_on_ohm', 'The voltage ranges work normally, but on every resistance range the pointer does not move when the probes are shorted together.', 'Resistance ranges depend on the battery and are protected by a fuse in series with the ohm circuit. If voltage works but all ohm ranges are dead, check the battery and the fuse first, and replace them only with the exact rating specified for the meter.', 2)
