insert into public.fault_scenarios (equipment_id, slug, symptom, explanation, sort_order) values ('analog_multimeter', 'pointer_pegged_right', 'As soon as the probes touch a mains-powered circuit on a high voltage range, the pointer slams against the right end. Before this, the selector was left on a current range from an earlier job.', 'A current range has a very low resistance, so connecting it across a voltage source is almost a short circuit. It can pin the pointer, blow the fuse, damage the meter and injure the user. Always set the correct function and range before touching the probes to a circuit.', 3)
