insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q1', 1, 'What is the correct way to read the pointer to avoid parallax error?', array['From the left side of the meter', 'From directly above so the pointer lines up with its mirror reflection', 'From as far away as possible', 'With the meter held upside down']::text[], 1, 'When the pointer and its mirror image coincide, your eye is directly above the pointer and the reading is free of parallax error.' from public.quizzes where equipment_id = 'analog_multimeter' and slug = 'analog_mm_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q2', 2, 'What is the purpose of the mechanical zero screw?', array['To set the pointer to zero on the left of the scale when nothing is connected', 'To calibrate the resistance ranges', 'To select the AC range', 'To open the battery cover']::text[], 0, 'The mechanical zero sets the resting position of the pointer at zero when the meter is not connected.' from public.quizzes where equipment_id = 'analog_multimeter' and slug = 'analog_mm_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q3', 3, 'Where is zero on the resistance (ohm) scale of an analog multimeter?', array['On the left', 'In the middle', 'It has no zero', 'On the right']::text[], 3, 'The ohm scale is reversed: zero ohm is at the right end (probes shorted) and infinity is at the left end (open circuit).' from public.quizzes where equipment_id = 'analog_multimeter' and slug = 'analog_mm_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q4', 4, 'What must you do after changing the resistance range?', array['Replace the fuse', 'Press HOLD', 'Re-zero the meter with the 0 ohm adjuster with the probes shorted', 'Reverse the probes']::text[], 2, 'Each resistance range uses a different internal circuit, so the 0 ohm adjustment must be repeated after every range change.' from public.quizzes where equipment_id = 'analog_multimeter' and slug = 'analog_mm_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q5', 5, 'You do not know how large a DC voltage is. Which range do you start with?', array['The lowest DC range', 'The highest DC voltage range', 'A resistance range', 'A current range']::text[], 1, 'Starting on the highest range protects the pointer and the meter. Then step down until the reading is easy to read.' from public.quizzes where equipment_id = 'analog_multimeter' and slug = 'analog_mm_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q6', 6, 'Which statement about measuring resistance is correct?', array['The circuit must be switched off and capacitors discharged', 'The circuit must be live', 'The reading is better if the circuit is powered', 'It can be done on any voltage range']::text[], 0, 'The meter supplies its own test current from its battery. External voltage gives wrong readings and can damage the meter.' from public.quizzes where equipment_id = 'analog_multimeter' and slug = 'analog_mm_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q7', 7, 'The pointer moves backwards (to the left of zero) when measuring DC voltage. What is the most likely cause?', array['The battery is flat', 'The range is too high', 'The fuse is blown', 'The probes are connected with reverse polarity']::text[], 3, 'The pointer deflects the wrong way when polarity is reversed. Swap the probes (after removing them from the circuit).' from public.quizzes where equipment_id = 'analog_multimeter' and slug = 'analog_mm_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q8', 8, 'How is current measured with the meter?', array['In parallel with the component', 'Across the voltage source', 'In series with the load', 'With the probes not touching anything']::text[], 2, 'The current must flow through the meter, so the meter is connected in series in the circuit.' from public.quizzes where equipment_id = 'analog_multimeter' and slug = 'analog_mm_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q9', 9, 'Why should the selector be set to OFF after measuring resistance?', array['To protect the scale from dust', 'On resistance ranges, touching the probes together can drain the battery', 'To reset the mechanical zero', 'To charge the battery']::text[], 1, 'On resistance ranges the battery supplies current whenever the probes touch, so storing the meter on an ohm range can drain or damage the battery.' from public.quizzes where equipment_id = 'analog_multimeter' and slug = 'analog_mm_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
