select id, 'q10', 10, 'Why can a pointer be read less accurately at the far left end of a voltage scale?', array['A small deflection gives low resolution, so a lower range should be chosen', 'The scale divisions are dirtier', 'The mirror does not reach there', 'The probes lose contact']::text[], 0, 'Readings are most accurate in the upper part of the scale. If the pointer is close to zero, select a lower range so it deflects more.' from public.quizzes where equipment_id = 'analog_multimeter' and slug = 'analog_mm_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
