-- ===== digital_clamp_meter =====
insert into public.equipment (id, name, category, summary, overview, model_asset, default_camera_orbit, model_credit, layout, published)
values ('digital_clamp_meter', 'Digital Clamp Meter', 'Measurement', 'Clamp-on meter that measures current through a conductor without breaking the circuit, plus voltage and resistance.', 'A digital clamp meter measures current by sensing the magnetic field around a single conductor held inside its jaws, so the circuit does not have to be opened. A trigger opens the jaws, a rotary switch selects the function, and the result appears on an LCD. Most clamp meters also have test lead jacks for voltage, resistance and continuity. Clamp around one conductor only, and always respect the meter''s CAT rating and maximum current. Based on UNI-T UT203.', 'models/digital_clamp_meter.glb', '0deg 75deg 0.6m', null, '{"units":"m","body":{"width":0.065,"height":0.19,"depth":0.03,"cornerRadius":0.004,"color":"#E0A526"},"parts":[{"id":"fixed_jaw","type":"handle","face":"top","position":[-0.02,0],"size":[0.014,0.024,0.045],"color":"#3A3A38"},{"id":"movable_jaw","type":"handle","face":"top","position":[0.02,0],"size":[0.014,0.024,0.045],"color":"#3A3A38"},{"id":"trigger","type":"button","face":"right","position":[0,0.06],"size":[0.014,0.03,0.008],"color":"#3A3A38"},{"id":"lcd_display","type":"screen","face":"front","position":[0,0.055],"size":[0.045,0.035,0.003],"color":"#9FB3A5"},{"id":"hold_button","type":"button","face":"front","position":[-0.014,0.02],"size":[0.02,0.01,0.004],"color":"#8C8B87"},{"id":"select_button","type":"button","face":"front","position":[0.014,0.02],"size":[0.02,0.01,0.004],"color":"#C9A64B"},{"id":"rotary_switch","type":"knob","face":"front","position":[0,-0.025],"size":[0.04,0.04,0.01],"color":"#3A3A38"},{"id":"vohm_jack","type":"port","face":"front","position":[0.014,-0.075],"size":[0.011,0.011,0.005],"color":"#A34A4A"},{"id":"com_jack","type":"port","face":"front","position":[-0.014,-0.075],"size":[0.011,0.011,0.005],"color":"#1F1F1E"},{"id":"test_leads","type":"probe","face":"left","position":[0,-0.07],"size":[0.006,0.006,0.045],"color":"#A34A4A"}]}'::jsonb, true)
on conflict (id) do update set name = excluded.name, category = excluded.category, summary = excluded.summary,
  overview = excluded.overview, model_asset = excluded.model_asset, default_camera_orbit = excluded.default_camera_orbit,
  model_credit = excluded.model_credit, layout = excluded.layout, published = true;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('digital_clamp_meter', 'fixed_jaw', 1, 'Fixed Jaw', 'The fixed half of the iron-core transformer jaw. Together with the movable jaw it forms a closed ring that senses the magnetic field around the conductor being measured.', 'Keep the jaw faces clean and the tips aligned with the movable jaw. Place one conductor in the middle of the ring when measuring.', array['Do not use the meter if the jaw or case is cracked.', 'Keep your fingers behind the hand guard (the ridge below the jaws) when clamping live conductors.']::text[], 'fixed_jaw')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('digital_clamp_meter', 'movable_jaw', 2, 'Movable Jaw', 'The jaw half that opens when the trigger is pressed so a conductor can enter the ring, and closes again under spring force.', 'Press the trigger to open the jaw, place a single conductor in the centre of the ring, then release the trigger so the jaws close completely. Dirt or a gap in the jaw faces causes errors.', array['Make sure the jaws are fully closed before reading; a gap gives a wrong, usually low, reading.', 'Never clamp a conductor larger than the maximum jaw opening shown in the manual.']::text[], 'movable_jaw')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('digital_clamp_meter', 'trigger', 3, 'Jaw Trigger', 'Lever on the side of the body that opens the movable jaw.', 'Squeeze the trigger to open the jaws and release it to close them around the conductor. Do not force the jaws open beyond their stop.', array['Do not use the trigger if the spring does not return the jaws fully; the meter should be repaired or replaced.']::text[], 'trigger')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('digital_clamp_meter', 'lcd_display', 4, 'LCD Display', 'Shows the measured value with its unit, the AC/DC symbol, polarity and status symbols such as HOLD, low battery and OL (over range).', 'Read the digits together with the unit shown. OL means the input exceeds the selected range or the circuit is open.', array['Do not trust a dim or flickering display; replace the battery before measuring.']::text[], 'lcd_display')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('digital_clamp_meter', 'rotary_switch', 5, 'Rotary Function Switch', 'Selects the function and range: AC or DC current, AC or DC voltage, resistance and continuity, and OFF. Some models also have frequency, capacitance and non-contact voltage positions.', 'Turn the switch to the required function before clamping or connecting leads. Use the highest range, or auto-range, when the value is unknown. Turn to OFF when finished.', array['Do not turn the switch while the jaws are clamped around a conductor that carries current or the leads are connected to a live circuit.', 'Set the switch to the correct function before connecting the leads.']::text[], 'rotary_switch')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('digital_clamp_meter', 'hold_button', 6, 'HOLD Button', 'Freezes the current reading on the display so it can be read after the meter is moved to a safe spot.', 'Press HOLD to freeze the value and press it again to release. The HOLD symbol shows on the display while active.', array['A held value does not update; release HOLD before taking a new measurement.']::text[], 'hold_button')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('digital_clamp_meter', 'select_button', 7, 'SELECT / Function Button', 'Cycles through functions that share a switch position (for example resistance, continuity and diode, or AC and DC), and on some models zeroes the DC current reading or switches on the backlight.', 'Press the button until the display shows the symbol of the mode you want. For DC current, zero the reading with the jaws closed and no conductor inside, as described in your meter''s manual.', array['Check the mode symbol on the display before measuring.']::text[], 'select_button')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('digital_clamp_meter', 'vohm_jack', 8, 'V/Ohm Jack', 'Positive input for voltage, resistance, continuity and diode tests with the test leads. It is not used for clamp current measurement.', 'Plug the red test lead into this jack when measuring voltage or resistance with the leads.', array['Remove the test leads from the jacks before measuring current with the jaws.', 'Do not connect the leads to a voltage higher than the meter''s rated maximum.']::text[], 'vohm_jack')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('digital_clamp_meter', 'com_jack', 9, 'COM Jack', 'Common (negative) input for the black test lead for voltage, resistance and continuity measurements.', 'Plug the black lead here. It is the reference for all lead measurements.', array['Connect the black lead first and disconnect it last when working on live circuits.']::text[], 'com_jack')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('digital_clamp_meter', 'test_leads', 10, 'Test Leads', 'Insulated leads, red (positive) and black (common), with probe tips for measuring voltage, resistance and continuity.', 'Insert the plugs into the V/Ohm and COM jacks and touch the tips to the measurement points. Keep your fingers behind the finger guards.', array['Use only leads rated at or above the CAT rating and voltage of the circuit and inspect them for damage before each use.', 'Unplug the leads when you use the jaws to measure current.']::text[], 'test_leads')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
delete from public.parts where equipment_id = 'digital_clamp_meter' and id not in ('fixed_jaw', 'movable_jaw', 'trigger', 'lcd_display', 'rotary_switch', 'hold_button', 'select_button', 'vohm_jack', 'com_jack', 'test_leads');
delete from public.safety_rules where equipment_id = 'digital_clamp_meter';
insert into public.safety_rules (equipment_id, sort_order, text) values ('digital_clamp_meter', 1, 'Check the meter''s CAT rating and voltage rating, and only use it on circuits within those limits.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('digital_clamp_meter', 2, 'Clamp around one conductor only. Enclosing both live and neutral of a cable makes the magnetic fields cancel and the reading is close to zero.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('digital_clamp_meter', 3, 'Never exceed the maximum current marked on the meter, and never use the jaws on uninsulated conductors above the rated voltage.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('digital_clamp_meter', 4, 'Inspect the meter, the jaws and the test leads for damage before use, and do not use a damaged meter.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('digital_clamp_meter', 5, 'Remove the test leads from the jacks when measuring current with the jaws, and set the switch to the function before clamping or connecting.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('digital_clamp_meter', 6, 'Keep your fingers behind the hand guard, and wear suitable personal protective equipment when working on live installations.');
