insert into public.fault_scenarios (equipment_id, slug, symptom, explanation, sort_order) values ('digital_clamp_meter', 'current_reads_near_zero', 'A running appliance clearly draws current, but the clamp meter shows almost 0 A when the jaws enclose its two-core cable.', 'A clamp meter measures the net magnetic field. In a two-core cable the currents are equal and opposite, so the net current is nearly zero. Separate and clamp a single conductor. A flat battery would blank or dim the display, and HOLD would freeze a number rather than show zero.', 1)
on conflict (equipment_id, slug) do update set symptom = excluded.symptom, explanation = excluded.explanation, sort_order = excluded.sort_order;
