insert into public.quizzes (equipment_id, slug, title, time_limit_sec, sort_order) values ('digital_clamp_meter', 'clamp_meter_basics', 'Clamp meter basics', null, 1)
on conflict (equipment_id, slug) do update set title = excluded.title, time_limit_sec = excluded.time_limit_sec, sort_order = excluded.sort_order;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q1', 1, 'What is the main advantage of a clamp meter for current measurement?', array['It needs no battery', 'It measures only voltage', 'It is cheaper than a multimeter', 'It measures current without breaking the circuit']::text[], 3, 'The jaws sense the magnetic field around the conductor, so the circuit does not have to be opened and the meter does not have to be wired in series.' from public.quizzes where equipment_id = 'digital_clamp_meter' and slug = 'clamp_meter_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q2', 2, 'You clamp around a two-core cable (live and neutral together) and the reading is near zero. Why?', array['The cable has no current', 'The jaws are too large', 'The fields of the two conductors cancel', 'The cable is overheating']::text[], 2, 'The currents in live and neutral are equal and opposite, so the net magnetic field is almost zero. Clamp a single conductor.' from public.quizzes where equipment_id = 'digital_clamp_meter' and slug = 'clamp_meter_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q3', 3, 'What is the correct position of the conductor in the jaws?', array['Touching the outside of the jaws', 'In the centre of the ring, with the jaws fully closed', 'Anywhere, the meter compensates', 'Wrapped several times around one jaw']::text[], 1, 'A centred conductor and fully closed jaws give the most accurate reading and reduce interference from other conductors.' from public.quizzes where equipment_id = 'digital_clamp_meter' and slug = 'clamp_meter_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q4', 4, 'What should be done with the test leads when measuring current with the jaws?', array['Remove them from the jacks', 'Plug them into the 10A jack', 'Short them together', 'Keep them in the COM jack only']::text[], 0, 'The leads are not used for jaw measurements. Removing them avoids confusion and a risk of touching live parts.' from public.quizzes where equipment_id = 'digital_clamp_meter' and slug = 'clamp_meter_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q5', 5, 'Which action is NOT safe?', array['Inspecting the jaws before use', 'Keeping fingers behind the hand guard', 'Checking the CAT rating', 'Turning the rotary switch while the jaws are clamped on a loaded conductor']::text[], 3, 'Changing the function while measuring a live conductor or circuit can give wrong readings and is unsafe. Remove the meter from the conductor first.' from public.quizzes where equipment_id = 'digital_clamp_meter' and slug = 'clamp_meter_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q6', 6, 'What does the OL symbol mean on the display?', array['Output low', 'The meter is locked', 'The value is over the selected range or the circuit is open', 'The battery is full']::text[], 2, 'OL means overload: the input is above the range, or there is an open circuit on a resistance range.' from public.quizzes where equipment_id = 'digital_clamp_meter' and slug = 'clamp_meter_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q7', 7, 'How do you measure AC voltage with a clamp meter?', array['Clamp around the live wire', 'Use the test leads in the V/Ohm and COM jacks, in parallel with the load', 'Use the leads in series with the load', 'Hold the meter near the wire']::text[], 1, 'Voltage is measured between two points with the leads, in parallel with the circuit. The jaws only measure current.' from public.quizzes where equipment_id = 'digital_clamp_meter' and slug = 'clamp_meter_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q8', 8, 'Why should the jaw faces be kept clean and closed?', array['A gap in the magnetic core reduces the signal and gives low, unstable readings', 'For appearance', 'To prevent electric shock only', 'To save the battery']::text[], 0, 'Dirt or an air gap breaks the magnetic path through the core, so the induced signal is smaller than it should be.' from public.quizzes where equipment_id = 'digital_clamp_meter' and slug = 'clamp_meter_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q9', 9, 'Before measuring DC current with a clamp meter, what is usually necessary?', array['Short the leads together', 'Press HOLD', 'Open the battery cover', 'Zero the reading with the jaws closed and empty']::text[], 3, 'A DC clamp sensor can have an offset, so it is zeroed with no conductor in the jaws, following the meter''s manual.' from public.quizzes where equipment_id = 'digital_clamp_meter' and slug = 'clamp_meter_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q10', 10, 'Which of these is the correct way to measure resistance with a clamp meter?', array['Clamp the resistor', 'Use the jaws on a live circuit', 'Use the leads on a de-energized circuit with the switch on the resistance range', 'Resistance cannot be measured']::text[], 2, 'Resistance is measured with the leads, on a circuit that is switched off and discharged, like with a multimeter.' from public.quizzes where equipment_id = 'digital_clamp_meter' and slug = 'clamp_meter_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
delete from public.quiz_questions where quiz_id = (select id from public.quizzes where equipment_id = 'digital_clamp_meter' and slug = 'clamp_meter_basics') and slug not in ('q1', 'q2', 'q3', 'q4', 'q5', 'q6', 'q7', 'q8', 'q9', 'q10');
delete from public.quizzes where equipment_id = 'digital_clamp_meter' and slug not in ('clamp_meter_basics');

-- ===== digital_oscilloscope =====
insert into public.equipment (id, name, category, summary, overview, model_asset, default_camera_orbit, model_credit, layout, published)
values ('digital_oscilloscope', 'Digital Oscilloscope', 'Measurement', 'Bench instrument that displays how a voltage changes over time, used to view, time and measure signals.', 'A digital oscilloscope samples an input voltage and draws it on a screen as a graph of voltage (vertical) against time (horizontal). Probes connect the circuit to the BNC channel inputs, the vertical and horizontal controls set the scale, and the trigger holds a repeating waveform steady. Always check the probe attenuation setting, and remember that the probe ground clip is connected to earth ground through the scope. Based on Rigol DS1054Z.', 'models/digital_oscilloscope.glb', '0deg 75deg 0.6m', null, '{"units":"m","body":{"width":0.32,"height":0.15,"depth":0.13,"cornerRadius":0.008,"color":"#CFCFCB"},"parts":[{"id":"screen","type":"screen","face":"front","position":[-0.055,0.012],"size":[0.19,0.105,0.003],"color":"#1E2A2E"},{"id":"softkeys","type":"button","face":"front","position":[-0.045,-0.058],"size":[0.15,0.012,0.004],"color":"#8C8B87"},{"id":"multifunction_knob","type":"knob","face":"front","position":[0.075,0.045],"size":[0.025,0.025,0.012],"color":"#4A4A48"},{"id":"run_stop_buttons","type":"button","face":"front","position":[0.118,0.052],"size":[0.04,0.012,0.004],"color":"#C9A64B"},{"id":"vertical_controls","type":"knob","face":"front","position":[0.068,0.01],"size":[0.028,0.028,0.012],"color":"#4A4A48"},{"id":"horizontal_controls","type":"knob","face":"front","position":[0.102,0.01],"size":[0.028,0.028,0.012],"color":"#4A4A48"},{"id":"trigger_controls","type":"knob","face":"front","position":[0.136,0.01],"size":[0.028,0.028,0.012],"color":"#4A4A48"},{"id":"bnc_inputs","type":"port","face":"front","position":[0.095,-0.058],"size":[0.09,0.016,0.015],"color":"#2B2B2B"},{"id":"probe_compensation","type":"port","face":"front","position":[0.147,-0.04],"size":[0.008,0.008,0.004],"color":"#C9A64B"},{"id":"power_button","type":"button","face":"front","position":[-0.14,-0.062],"size":[0.01,0.01,0.004],"color":"#A34A4A"}]}'::jsonb, true)
on conflict (id) do update set name = excluded.name, category = excluded.category, summary = excluded.summary,
  overview = excluded.overview, model_asset = excluded.model_asset, default_camera_orbit = excluded.default_camera_orbit,
  model_credit = excluded.model_credit, layout = excluded.layout, published = true;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('digital_oscilloscope', 'screen', 1, 'Display Screen', 'Shows the captured waveforms as voltage against time on a grid, together with channel settings, the timebase, trigger status and automatic measurements.', 'Read the volts per division and seconds per division at the screen edges, then count grid divisions to estimate amplitude and period. Use the on-screen measurements or cursors for exact values.', array['Do not trust a trace until you have checked the vertical scale, timebase and probe attenuation shown on screen.']::text[], 'screen')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('digital_oscilloscope', 'softkeys', 2, 'Menu Softkeys', 'A row of keys below the screen whose function changes with the menu shown above them on the display.', 'Press the key under the menu item you want, and turn the multifunction knob to change values or options in that menu.', array['Read the menu label before pressing a softkey; some entries such as Default or Clear reset the settings or stored data.']::text[], 'softkeys')
