  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('digital_oscilloscope', 'multifunction_knob', 3, 'Multifunction Knob', 'Rotary knob that adjusts the selected menu item, scrolls through lists and, when pressed, confirms a choice.', 'Turn it to change a highlighted value, such as a cursor position or the probe ratio, and press it to select. Many models also use it to adjust waveform brightness.', array['Check the value on the screen after changing it, so that an accidental turn does not leave a wrong setting.']::text[], 'multifunction_knob')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('digital_oscilloscope', 'run_stop_buttons', 4, 'RUN/STOP, SINGLE and AUTO Buttons', 'RUN/STOP starts or freezes continuous acquisition, SINGLE captures one trigger event and then stops, and AUTO sets up the vertical, horizontal and trigger controls automatically for a suitable display.', 'Press STOP to freeze a trace for measurement and RUN to resume. Use SINGLE for one-off events, and AUTO as a quick starting point for an unknown repetitive signal.', array['A stopped display does not update. Press RUN before drawing conclusions about a live signal.', 'Autoset can change the settings you had; note them first if you need to repeat a measurement.']::text[], 'run_stop_buttons')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('digital_oscilloscope', 'vertical_controls', 5, 'Vertical Controls', 'The channel buttons (CH1 to CH4) switch each channel on or off, and each channel has a POSITION knob to move the trace up or down and a SCALE knob to set volts per division.', 'Press the channel button, then turn SCALE until the waveform fills most of the screen without clipping. Use POSITION to place the zero level where it is easy to read.', array['Choose a vertical scale high enough for the expected voltage, and never exceed the maximum input voltage marked on the scope or probe.']::text[], 'vertical_controls')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('digital_oscilloscope', 'horizontal_controls', 6, 'Horizontal Controls', 'The horizontal SCALE knob sets seconds per division (the timebase) and the POSITION knob moves the waveform in time relative to the trigger point.', 'Turn SCALE so that two to five periods of the signal are visible, and use POSITION to look before or after the trigger event.', array['If the timebase is too slow, a fast signal appears as a false, wrong-frequency waveform (aliasing), so check the frequency against an expected value.']::text[], 'horizontal_controls')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('digital_oscilloscope', 'trigger_controls', 7, 'Trigger Controls', 'The trigger decides when a capture starts so that a repeating waveform appears steady. The LEVEL knob sets the voltage at which the trigger fires, and keys select the mode (Auto, Normal, Single), the source and a forced trigger.', 'Set the trigger source to the channel you are viewing, choose the rising or falling edge, and turn LEVEL until it lies within the signal swing. The waveform should then stop drifting.', array['In Normal mode, the display stays frozen when no trigger occurs and looks like a dead signal. Switch to Auto if you are not sure.']::text[], 'trigger_controls')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('digital_oscilloscope', 'bnc_inputs', 8, 'Channel BNC Inputs', 'Coaxial BNC connectors, one per channel, where probes or cables are attached. The outer shell of each BNC is connected to earth ground.', 'Push the probe BNC onto the input and twist it to lock. Set the probe attenuation in the channel menu to match the switch on the probe (1X or 10X).', array['The BNC shell and probe ground clip are at earth potential, so never clip the ground lead to a live or non-earth-referenced point, because it creates a short circuit.', 'Stay within the maximum input voltage printed beside the inputs (typically a few hundred volts on teaching scopes, not mains).']::text[], 'bnc_inputs')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('digital_oscilloscope', 'probe_compensation', 9, 'Probe Compensation Terminal', 'Outputs a small test square wave (typically about 1 kHz, 3 V peak to peak) with a ground terminal beside it, used to adjust 10X probes and to check the scope.', 'Clip the probe tip to the signal terminal and the ground clip to the ground terminal. Adjust the small trimmer on the probe until the square wave edges are flat and sharp.', array['Use this terminal only for compensating probes; it is not a power source.']::text[], 'probe_compensation')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('digital_oscilloscope', 'power_button', 10, 'Power Button', 'Turns the oscilloscope on or puts it into standby.', 'Press once to power on and wait for start-up to finish before connecting probes. Press again to power off after use.', array['Use the supplied grounded (three-pin) power cord and do not defeat the earth connection, since the scope chassis relies on it for safety.']::text[], 'power_button')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
delete from public.parts where equipment_id = 'digital_oscilloscope' and id not in ('screen', 'softkeys', 'multifunction_knob', 'run_stop_buttons', 'vertical_controls', 'horizontal_controls', 'trigger_controls', 'bnc_inputs', 'probe_compensation', 'power_button');
delete from public.safety_rules where equipment_id = 'digital_oscilloscope';
insert into public.safety_rules (equipment_id, sort_order, text) values ('digital_oscilloscope', 1, 'Use the grounded power cord and never remove or bypass the earth pin; the probe ground clips are connected to earth through the scope.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('digital_oscilloscope', 2, 'Connect the probe ground clip only to a circuit point that is at ground potential, and do not measure two different non-ground points with two grounded channel probes at the same time.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('digital_oscilloscope', 3, 'Do not connect the scope or standard probes directly to mains voltage or to voltages above the rating marked on the instrument and probe; use a rated differential probe and ask the instructor.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('digital_oscilloscope', 4, 'Match the probe attenuation setting (1X or 10X) to the probe switch before reading values.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('digital_oscilloscope', 5, 'Check probes and cables for damage before use, and do not use a scope with a damaged case or probe insulation.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('digital_oscilloscope', 6, 'Do not open the case; high voltages remain inside after power-off.');
