insert into public.fault_scenarios (equipment_id, slug, symptom, explanation, sort_order) values ('digital_oscilloscope', 'drifting_waveform', 'A 1 kHz sine wave scrolls sideways across the screen and cannot be held steady.', 'A steady display depends on triggering on the same point of every cycle. If the trigger source is another channel, or the LEVEL lies outside the signal swing, the scope triggers randomly, so the picture drifts.', 1)
