insert into public.fault_scenarios (equipment_id, slug, symptom, explanation, sort_order) values ('digital_oscilloscope', 'amplitude_ten_times_wrong', 'A 1 V peak-to-peak signal from a generator is read as 10 V peak-to-peak on the screen, with a 10X probe in use.', 'The scope multiplies the measured voltage by the probe ratio set in the channel menu. If the probe switch is on 1X but the menu says 10X, the readings are ten times too large. They would be ten times too small the other way round.', 2)
