select id, 'q5', 5, 'The probe is switched to 10X. What must you do in the scope?', array['Set the channel probe ratio to 10X', 'Nothing, the scope detects it by itself on every model', 'Set the timebase to 10 ms', 'Press SINGLE']::text[], 0, 'The scope must be told the attenuation; otherwise voltage readings are scaled wrongly.' from public.quizzes where equipment_id = 'digital_oscilloscope' and slug = 'scope_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q6', 6, 'Why must you be careful where the probe ground clip is connected?', array['It only affects the colour of the trace', 'It changes the timebase', 'It is not connected to anything', 'It is connected to earth through the scope, so clipping it to a live point creates a short circuit']::text[], 3, 'The ground of the probe is at earth potential, so connecting it to a non-ground point can short that point to earth.' from public.quizzes where equipment_id = 'digital_oscilloscope' and slug = 'scope_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q7', 7, 'What is the probe compensation terminal used for?', array['Charging the scope battery', 'Powering a circuit under test', 'Adjusting 10X probes using a test square wave', 'Calibrating the timebase of the circuit']::text[], 2, 'The built-in square wave lets you trim the probe so that the edges are flat.' from public.quizzes where equipment_id = 'digital_oscilloscope' and slug = 'scope_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q8', 8, 'What does the SINGLE button do?', array['Shows only CH1', 'Captures one trigger event and then stops', 'Turns off the display', 'Selects 1X attenuation']::text[], 1, 'SINGLE arms the trigger for a single capture and then stops acquisition.' from public.quizzes where equipment_id = 'digital_oscilloscope' and slug = 'scope_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q9', 9, 'The trace does not move in Normal trigger mode and the signal is below the trigger level. What is the likely reason?', array['No trigger occurs, so the display is not updated; try Auto mode or adjust LEVEL', 'The scope is broken', 'The probe is too long', 'The timebase is too slow only']::text[], 0, 'Normal mode waits for a trigger and shows nothing new when there is none.' from public.quizzes where equipment_id = 'digital_oscilloscope' and slug = 'scope_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q10', 10, 'Which is the safest practice for measuring a circuit with a standard passive probe?', array['Use the ground clip on the hot mains line', 'Remove the earth pin of the power cord to reduce noise', 'Use the probe tip on the 230 V mains directly', 'Connect the ground clip to the circuit ground and stay within the voltage rating of the probe and scope']::text[], 3, 'The ground clip goes to the circuit ground, and the ratings of the scope and probe must never be exceeded. Never defeat the earth pin.' from public.quizzes where equipment_id = 'digital_oscilloscope' and slug = 'scope_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
