delete from public.quizzes where equipment_id = 'digital_oscilloscope' and slug not in ('scope_basics');

-- ===== function_generator =====
insert into public.equipment (id, name, category, summary, overview, model_asset, default_camera_orbit, model_credit, layout, published)
values ('function_generator', 'Function Generator', 'Sources', 'Bench source that produces sine, square, ramp and other test waveforms with adjustable frequency, amplitude and offset.', 'A function generator creates repeating electrical waveforms such as sine, square, ramp and pulse for testing circuits. You pick the waveform, then set frequency, amplitude and DC offset on a screen using softkeys, a keypad and a knob. The signal leaves through BNC output connectors with a typical 50 ohm source impedance, so the output load setting must match the real load. Based on Rigol DG1022Z.', 'models/function_generator.glb', '0deg 75deg 0.55m', null, '{"units":"m","body":{"width":0.3,"height":0.13,"depth":0.12,"cornerRadius":0.008,"color":"#D9D7D2"},"parts":[{"id":"lcd_screen","type":"screen","face":"front","position":[-0.06,0.018],"size":[0.11,0.075,0.003],"color":"#2E4A5C"},{"id":"softkeys","type":"button","face":"front","position":[-0.06,-0.032],"size":[0.11,0.01,0.004],"color":"#8C8B87"},{"id":"waveform_keys","type":"button","face":"front","position":[0.035,0.045],"size":[0.07,0.012,0.004],"color":"#C9A64B"},{"id":"mode_keys","type":"button","face":"front","position":[0.035,0.026],"size":[0.07,0.012,0.004],"color":"#8C8B87"},{"id":"numeric_keypad","type":"button","face":"front","position":[0.115,0.03],"size":[0.05,0.05,0.004],"color":"#8C8B87"},{"id":"rotary_knob","type":"knob","face":"front","position":[0.07,-0.016],"size":[0.026,0.026,0.012],"color":"#4A4A48"},{"id":"bnc_outputs","type":"port","face":"front","position":[-0.07,-0.048],"size":[0.07,0.014,0.014],"color":"#2B2B2B"},{"id":"output_buttons","type":"button","face":"front","position":[0,-0.047],"size":[0.03,0.01,0.004],"color":"#4A7BA3"},{"id":"counter_input","type":"port","face":"front","position":[0.07,-0.047],"size":[0.012,0.012,0.012],"color":"#2B2B2B"},{"id":"power_button","type":"button","face":"front","position":[0.125,-0.047],"size":[0.01,0.01,0.004],"color":"#A34A4A"}]}'::jsonb, true)
on conflict (id) do update set name = excluded.name, category = excluded.category, summary = excluded.summary,
  overview = excluded.overview, model_asset = excluded.model_asset, default_camera_orbit = excluded.default_camera_orbit,
  model_credit = excluded.model_credit, layout = excluded.layout, published = true;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('function_generator', 'lcd_screen', 1, 'LCD Screen', 'Shows the selected waveform, its frequency, amplitude, offset and phase, the output state of each channel and the current menu.', 'Check the parameter values on the screen before enabling an output. The highlighted parameter is the one the knob and keypad will change.', array['Always read the amplitude and offset shown on screen before enabling the output.']::text[], 'lcd_screen')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('function_generator', 'softkeys', 2, 'Menu Softkeys', 'Keys below the screen whose function changes with the menu label shown above each one.', 'Press the key under a label to select a parameter (for example Frequency, Amplitude or Offset) or to change the unit.', array['Check the label above the key before pressing, since softkeys change function between menus.']::text[], 'softkeys')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('function_generator', 'waveform_keys', 3, 'Waveform Keys', 'Dedicated keys that select the output waveform, typically Sine, Square, Ramp, Pulse, Noise and Arbitrary.', 'Press the key for the waveform you need and then set its parameters. Square and pulse waves use a duty cycle parameter.', array['Changing the waveform can change the output level, so keep the output off while switching to an unfamiliar waveform.']::text[], 'waveform_keys')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('function_generator', 'mode_keys', 4, 'Mode and Utility Keys', 'Select modulation (Mod), sweep (Sweep), burst (Burst) and the utility menu (Utility) where the output load, sync and other system settings are found.', 'Press Mod, Sweep or Burst to add these features to the basic waveform. Use Utility to find the channel settings, including the output impedance (load) setting.', array['Leave the modulation and sweep modes off for basic measurements, so that the signal is a plain waveform.']::text[], 'mode_keys')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('function_generator', 'numeric_keypad', 5, 'Numeric Keypad', 'Enters exact parameter values using digits, a decimal point and a sign key, with the unit chosen through the softkeys.', 'Select a parameter, type the value on the keypad and press the unit softkey (such as kHz or Vpp) to confirm.', array['Check the unit before confirming; entering 1 kHz instead of 1 MHz changes the signal a thousand-fold.']::text[], 'numeric_keypad')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('function_generator', 'rotary_knob', 6, 'Rotary Knob and Arrow Keys', 'Adjusts the highlighted digit of a parameter with the knob, with the left and right arrow keys choosing which digit changes.', 'Use the arrow keys to select a digit, then turn the knob to step the value up or down for fine adjustment. Pressing the knob may confirm a selection on some menus.', array['Turn gradually when a circuit is connected, because a sudden amplitude increase can overstress a component.']::text[], 'rotary_knob')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('function_generator', 'bnc_outputs', 7, 'Channel Output Connectors (CH1, CH2)', 'BNC connectors that carry the generated signal, one per channel. The source impedance is normally 50 ohms, and the BNC outer shell is connected to ground.', 'Connect a BNC cable or lead from the output to the circuit input or to the oscilloscope. Connect the shell side to the circuit ground.', array['Do not apply an external voltage to the output connector, because it can damage the output stage.', 'The shell is at ground potential, so do not connect it to a voltage point other than ground.']::text[], 'bnc_outputs')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('function_generator', 'output_buttons', 8, 'Output Enable Buttons', 'Switch each channel output on or off. The key lights up while the output is active.', 'Set all parameters with the output off, connect the cable, then press the button to turn the signal on. Press again to turn it off before changing any connection.', array['Keep the output off whenever you connect or disconnect leads.']::text[], 'output_buttons')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('function_generator', 'counter_input', 9, 'Counter Input', 'BNC input for the built-in frequency counter, which measures the frequency or period of an external signal.', 'Connect the signal under test to the counter input and enable the counter in the utility menu. Read the frequency on the screen.', array['Stay within the maximum input level given for the counter input and never connect mains voltage.']::text[], 'counter_input')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('function_generator', 'power_button', 10, 'Power Button', 'Turns the function generator on and off.', 'Press to switch on and wait until the start-up screen disappears before connecting a circuit.', array['Use the supplied grounded power cord and keep the vents clear.']::text[], 'power_button')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
