insert into public.fault_scenarios (equipment_id, slug, symptom, explanation, sort_order) values ('function_generator', 'amplitude_double', 'The generator is set to 2 Vpp, but an oscilloscope with a 1 Mohm input shows about 4 Vpp.', 'With the 50 ohm load setting, the generator assumes that half of the voltage is lost across its own output impedance, so it doubles the open-circuit voltage. With a high-impedance real load, the full doubled voltage appears. Set the load to High Z, or terminate with 50 ohm.', 1)
