insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q1', 1, 'What does a function generator produce?', array['A stable DC supply only', 'A high-power AC current', 'Repeating waveforms such as sine, square and ramp', 'Only noise']::text[], 2, 'It is a signal source for testing, producing standard waveforms of adjustable frequency and amplitude.' from public.quizzes where equipment_id = 'function_generator' and slug = 'fg_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q2', 2, 'What is the typical source impedance of the output BNC?', array['1 ohm', '50 ohm', '1 Mohm', 'Zero']::text[], 1, 'Most generators have a 50 ohm output impedance, so the load matters for the real output voltage.' from public.quizzes where equipment_id = 'function_generator' and slug = 'fg_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
