select id, 'q3', 3, 'Why should the output be off while you connect leads?', array['To avoid unexpected signals or levels reaching the circuit', 'To save power', 'To change the language', 'Connecting leads needs it off for the knob to work']::text[], 0, 'An unexpected level can damage a circuit or an instrument input.' from public.quizzes where equipment_id = 'function_generator' and slug = 'fg_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
