select id, 'q4', 4, 'A sine wave has 4 Vpp. What is its peak voltage?', array['4 V', '8 V', '1.4 V', '2 V']::text[], 3, 'Peak is half of the peak-to-peak value, so 2 V.' from public.quizzes where equipment_id = 'function_generator' and slug = 'fg_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
