select id, 'q6', 6, 'What does the duty cycle of a square wave describe?', array['The peak voltage', 'The percentage of the period during which the signal is high', 'The number of cycles in a burst', 'The offset']::text[], 1, 'A duty cycle of 50 percent means equal high and low times.' from public.quizzes where equipment_id = 'function_generator' and slug = 'fg_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q7', 7, 'A generator is set to 50 ohm load but drives a high-impedance oscilloscope. What happens to the reading?', array['It is about double the displayed amplitude', 'It is half the displayed amplitude', 'It is exactly correct', 'It is zero']::text[], 0, 'The generator assumes the load divides the voltage in half, so with an open (high-impedance) load the real voltage is about double.' from public.quizzes where equipment_id = 'function_generator' and slug = 'fg_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
