-- ===== dc_power_supply =====
insert into public.equipment (id, name, category, summary, overview, model_asset, default_camera_orbit, model_credit, layout, published)
values ('dc_power_supply', 'DC Power Supply', 'Sources', 'Bench source that provides an adjustable DC voltage with an adjustable current limit to power circuits under test.', 'A benchtop DC power supply delivers a steady, adjustable DC voltage and limits the current to a value you set. Two displays show the output voltage and current, and coarse and fine knobs set each. In constant-voltage (CV) mode the supply holds the set voltage; if the load tries to draw more than the current limit, it switches to constant-current (CC) mode and the voltage drops. Based on GW Instek GPS-3030D.', 'models/dc_power_supply.glb', '0deg 75deg 0.55m', null, '{"units":"m","body":{"width":0.21,"height":0.14,"depth":0.3,"cornerRadius":0.008,"color":"#CFCFCB"},"parts":[{"id":"voltage_display","type":"display","face":"front","position":[-0.045,0.04],"size":[0.07,0.025,0.003],"color":"#7A2E2E"},{"id":"current_display","type":"display","face":"front","position":[0.045,0.04],"size":[0.07,0.025,0.003],"color":"#7A2E2E"},{"id":"voltage_knobs","type":"knob","face":"front","position":[-0.05,-0.005],"size":[0.05,0.04,0.014],"color":"#4A4A48"},{"id":"current_knobs","type":"knob","face":"front","position":[0.05,-0.005],"size":[0.05,0.04,0.014],"color":"#4A4A48"},{"id":"cv_cc_leds","type":"led","face":"front","position":[0,0.01],"size":[0.024,0.016,0.003],"color":"#0F7B6C"},{"id":"output_button","type":"button","face":"front","position":[0,-0.02],"size":[0.024,0.012,0.004],"color":"#C9A64B"},{"id":"power_switch","type":"switch","face":"front","position":[-0.075,-0.05],"size":[0.015,0.015,0.006],"color":"#A34A4A"},{"id":"negative_terminal","type":"port","face":"front","position":[-0.03,-0.048],"size":[0.016,0.016,0.015],"color":"#2B2B2B"},{"id":"ground_terminal","type":"port","face":"front","position":[0,-0.048],"size":[0.016,0.016,0.015],"color":"#0F7B6C"},{"id":"positive_terminal","type":"port","face":"front","position":[0.03,-0.048],"size":[0.016,0.016,0.015],"color":"#E03E3E"}]}'::jsonb, true)
on conflict (id) do update set name = excluded.name, category = excluded.category, summary = excluded.summary,
  overview = excluded.overview, model_asset = excluded.model_asset, default_camera_orbit = excluded.default_camera_orbit,
  model_credit = excluded.model_credit, layout = excluded.layout, published = true;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('dc_power_supply', 'voltage_display', 1, 'Voltage Display', 'Shows the output voltage in volts.', 'Read it to confirm the voltage set with the voltage knobs. With the output off, many supplies show the set value; with a load, it shows the actual output.', array['Check the displayed voltage before connecting a sensitive circuit.']::text[], 'voltage_display')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('dc_power_supply', 'current_display', 2, 'Current Display', 'Shows the output current in amperes.', 'Read the load current while the circuit is running. It also shows the current limit setting at the moment the output is short-circuited during setup.', array['A current much higher than expected indicates a fault in the circuit, so switch the output off and investigate.']::text[], 'current_display')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('dc_power_supply', 'voltage_knobs', 3, 'Voltage Knobs (Coarse / Fine)', 'Set the output voltage. The COARSE knob changes it in large steps and the FINE knob gives small adjustments.', 'Turn COARSE close to the required value and then use FINE for exact setting while watching the voltage display.', array['Start from zero, turn up slowly, and never set a voltage above the rating of the circuit under test.']::text[], 'voltage_knobs')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('dc_power_supply', 'current_knobs', 4, 'Current Limit Knobs (Coarse / Fine)', 'Set the maximum current that the supply allows. If the load tries to draw more, the supply goes into constant-current mode and the voltage drops.', 'Set the limit slightly above the current the circuit should normally draw. It protects components and wiring against excess current.', array['Set the current limit before connecting the circuit and use a conservatively low value for new or untested circuits.']::text[], 'current_knobs')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('dc_power_supply', 'cv_cc_leds', 5, 'CV / CC Indicator LEDs', 'Show the operating mode: CV (constant voltage) lights in normal operation, CC (constant current) lights when the current limit is active.', 'Normally the CV light is on. If the CC light comes on, the load is demanding more than the limit and the voltage is being reduced.', array['A lit CC light during normal operation means an overload or short circuit; check the circuit before raising the current limit.']::text[], 'cv_cc_leds')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('dc_power_supply', 'output_button', 6, 'Output ON/OFF Button', 'Connects or disconnects the output terminals from the supply without switching off the power.', 'Set voltage and limit with the output off, connect the circuit, then press the button to energise it. Press again to remove power. Some basic models have no such button, so check your unit.', array['Switch the output off before changing connections.']::text[], 'output_button')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('dc_power_supply', 'power_switch', 7, 'Power Switch', 'Turns the supply on and off at the mains.', 'Switch on after the supply is connected to the mains and before setting the voltage. Switch off when finished.', array['Use the grounded mains cord provided, and do not remove the earth connection.']::text[], 'power_switch')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('dc_power_supply', 'negative_terminal', 8, 'Negative (-) Terminal', 'Black output terminal, the negative side of the DC output. It is normally floating relative to the earth.', 'Connect the black lead here and to the negative (ground) side of the circuit.', array['Do not connect the output terminal directly to the earth terminal or mains-referenced points without understanding the circuit.']::text[], 'negative_terminal')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('dc_power_supply', 'ground_terminal', 9, 'Ground (GND) Terminal', 'Green terminal connected to the chassis and the mains earth. It allows the output to be grounded if the circuit requires it, using a link to the negative or positive terminal.', 'Leave it unconnected unless the circuit needs a ground reference. Use a short link to the negative terminal only when instructed.', array['Do not connect the red positive terminal to GND by mistake, as it shorts the output to earth.']::text[], 'ground_terminal')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('dc_power_supply', 'positive_terminal', 10, 'Positive (+) Terminal', 'Red output terminal, the positive side of the DC output.', 'Connect the red lead here and to the positive input of the circuit under test.', array['Check the polarity of the circuit before enabling the output, since reverse polarity damages polarised components such as electrolytic capacitors and ICs.']::text[], 'positive_terminal')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
delete from public.parts where equipment_id = 'dc_power_supply' and id not in ('voltage_display', 'current_display', 'voltage_knobs', 'current_knobs', 'cv_cc_leds', 'output_button', 'power_switch', 'negative_terminal', 'ground_terminal', 'positive_terminal');
delete from public.safety_rules where equipment_id = 'dc_power_supply';
insert into public.safety_rules (equipment_id, sort_order, text) values ('dc_power_supply', 1, 'Set the voltage and current limit first, with the output off, and only then connect the circuit.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('dc_power_supply', 2, 'Check polarity (red to positive, black to negative) before enabling the output, and never exceed the voltage rating of any component.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('dc_power_supply', 3, 'Switch the output off before changing connections or touching the circuit.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('dc_power_supply', 4, 'Do not short the output terminals deliberately except during the short-circuit current-limit setting procedure, and use short, thick leads for that.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('dc_power_supply', 5, 'Use the grounded mains cord, and do not open the case, because mains voltage is present inside.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('dc_power_supply', 6, 'If the CC light stays on or the supply gets hot, switch off and look for a short circuit or overload.');
