insert into public.fault_scenarios (equipment_id, slug, symptom, explanation, sort_order) values ('dc_power_supply', 'voltage_collapses', 'The voltage is set to 12 V, but when the circuit is connected the voltage display falls to 3 V, the current display reads the limit value and the CC light is on.', 'In constant-current mode, the supply lowers the voltage so that the current does not exceed the limit. This protects the circuit but shows that the load is drawing too much, possibly because of a short circuit, a wiring error or a limit set too low.', 1)
