select id, 'q1', 1, 'What does the CC light mean?', array['The cable is charged', 'The cooling fan is on', 'The supply is in standby', 'The supply is limiting the current (constant-current mode)']::text[], 3, 'CC means the load is trying to draw more than the set current limit.' from public.quizzes where equipment_id = 'dc_power_supply' and slug = 'psu_basics'
