select id, 'q2', 2, 'What is the purpose of the current limit?', array['To increase the voltage', 'To make the display brighter', 'To protect the circuit and wiring against excess current', 'To select AC output']::text[], 2, 'It limits the current so that a fault does not damage components.' from public.quizzes where equipment_id = 'dc_power_supply' and slug = 'psu_basics'
