select id, 'q4', 4, 'What should you do before connecting a circuit?', array['Set voltage and current limit with the output off', 'Turn all knobs to maximum', 'Short the GND terminal to the positive terminal', 'Remove the mains cord']::text[], 0, 'Preset the supply safely, so that the circuit sees the right values from the start.' from public.quizzes where equipment_id = 'dc_power_supply' and slug = 'psu_basics'
