select id, 'q6', 6, 'A circuit takes 0.5 A at 5 V. Which current limit is the most sensible?', array['30 A', '0 A', 'A little above 0.5 A, such as 0.6 to 1 A', 'Any value, it is irrelevant']::text[], 2, 'A limit just above the normal current protects the circuit.' from public.quizzes where equipment_id = 'dc_power_supply' and slug = 'psu_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
