-- ===== soldering_station =====
insert into public.equipment (id, name, category, summary, overview, model_asset, default_camera_orbit, model_credit, layout, published)
values ('soldering_station', 'Soldering Station', 'Assembly', 'Temperature-controlled soldering iron station for joining components to circuit boards.', 'A soldering station is a base unit with a digital temperature controller and a low-voltage soldering iron on a cable. The controller keeps the tip at the set temperature while the iron rests in a stand with a tip cleaner. The iron melts solder to form electrical and mechanical joints between component leads and printed circuit board pads. The tip reaches several hundred degrees Celsius, so burns and fumes are the main hazards. Based on Hakko FX-888D.', 'models/soldering_station.glb', '-20deg 65deg 0.55m', null, '{"units":"m","body":{"width":0.13,"height":0.095,"depth":0.17,"cornerRadius":0.008,"color":"#2F3237"},"parts":[{"id":"temperature_display","type":"display","face":"front","position":[-0.02,0.015],"size":[0.05,0.025,0.003],"color":"#C0392B"},{"id":"up_button","type":"button","face":"front","position":[0.035,0.02],"size":[0.02,0.012,0.004],"color":"#8C8B87"},{"id":"enter_button","type":"button","face":"front","position":[0.035,0.003],"size":[0.02,0.012,0.004],"color":"#C9A64B"},{"id":"power_switch","type":"switch","face":"front","position":[-0.04,-0.025],"size":[0.016,0.012,0.006],"color":"#E9E9E7"},{"id":"iron_connector","type":"port","face":"front","position":[0.035,-0.028],"size":[0.014,0.014,0.01],"color":"#1E1E1E"},{"id":"iron_stand","type":"handle","face":"top","position":[0.03,0],"size":[0.05,0.08,0.035],"color":"#8C8B87"},{"id":"tip_cleaner","type":"slot","face":"top","position":[-0.03,0],"size":[0.05,0.06,0.01],"color":"#D8B04A"},{"id":"soldering_iron","type":"probe","face":"left","position":[0,0],"size":[0.012,0.012,0.05],"color":"#A34A4A"}]}'::jsonb, true)
on conflict (id) do update set name = excluded.name, category = excluded.category, summary = excluded.summary,
  overview = excluded.overview, model_asset = excluded.model_asset, default_camera_orbit = excluded.default_camera_orbit,
  model_credit = excluded.model_credit, layout = excluded.layout, published = true;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('soldering_station', 'temperature_display', 1, 'Temperature Display', 'Shows the actual tip temperature while heating and in use, and shows the set temperature while it is being changed. A heater symbol or indicator shows when the heater is on.', 'Wait until the displayed temperature has settled at the set value before soldering. Check that the unit (degrees Celsius or Fahrenheit) is the one you expect.', array['The tip stays hot after the display value drops, so treat it as hot until it is fully cool.']::text[], 'temperature_display')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('soldering_station', 'up_button', 2, 'UP Button', 'Raises the set temperature value or steps through the stored preset temperatures, depending on the mode.', 'Press UP to increase the value shown while in the setting mode. Confirm the change with the ENTER button.', array['Do not use a higher temperature than the job needs; excess heat damages pads and components and shortens tip life.']::text[], 'up_button')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('soldering_station', 'enter_button', 3, 'ENTER Button', 'Confirms the selected temperature or setting and switches between the normal operating display and the setting modes.', 'Press ENTER to accept a change. If no button is pressed for a while, the station returns to its normal operating display.', array['Check the confirmed value on the display before you start soldering.']::text[], 'enter_button')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('soldering_station', 'power_switch', 4, 'Power Switch', 'Turns the station and its heater on and off.', 'Switch on with the iron seated in its stand and wait for the display to reach the set temperature. Switch off after use and leave the iron in the stand to cool.', array['Never leave the station switched on and unattended.', 'Switch off and unplug before changing the tip or cleaning the unit.']::text[], 'power_switch')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('soldering_station', 'iron_connector', 5, 'Iron Connector', 'Socket that connects the soldering iron cable to the station. It carries the low-voltage heater supply and the temperature sensor signal.', 'Switch the station off, push the iron plug fully in and screw or lock it if the plug has a retaining ring. Do not pull on the cable to disconnect; hold the plug.', array['Connect or disconnect the iron only with the station switched off and unplugged.', 'Do not use an iron with a damaged or frayed cable.']::text[], 'iron_connector')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('soldering_station', 'soldering_iron', 6, 'Soldering Iron', 'The hand tool with a heating element and a replaceable tip. Its heat melts solder and heats the pad and component lead so the solder flows into the joint.', 'Hold it like a pen near the front of the handle. Touch the tip to both the pad and the lead together, then feed solder to the joint rather than to the tip itself. Return it to the stand after each use.', array['Always return the iron to the stand; never place it on the bench or point it at anyone.', 'Do not touch the metal barrel or tip, and keep the cable away from the hot tip.']::text[], 'soldering_iron')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('soldering_station', 'iron_stand', 7, 'Iron Stand', 'Heat-resistant holder that keeps the hot iron off the bench and safely away from the cable, your hands and other objects.', 'Place the iron fully in the holder every time you stop soldering, even for a few seconds. Keep the stand on a stable surface with the station.', array['Make sure the iron is seated securely so it cannot roll or fall out.', 'Keep flammable materials such as paper and plastic away from the stand.']::text[], 'iron_stand')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('soldering_station', 'tip_cleaner', 8, 'Tip Cleaner', 'A damp sponge or brass wool tray used to wipe oxidation and old solder off the tip so it can transfer heat well.', 'Wipe the tip lightly on the damp sponge or brass wool before and after soldering, then add a fresh coat of solder to the tip. Keep a sponge damp, not wet.', array['Sponge water can spit when it touches a hot tip; wipe gently and keep your face back.', 'Never shake the iron to remove solder; molten drops can land on skin or the bench.']::text[], 'tip_cleaner')
