insert into public.safety_rules (equipment_id, sort_order, text) values ('soldering_station', 1, 'Treat the tip as hot at all times. Always return the iron to its stand and never lay it on the bench.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('soldering_station', 2, 'Solder in a well-ventilated area, ideally with a fume extractor, and keep your face out of the fume plume. Solder flux fumes irritate the lungs and eyes.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('soldering_station', 3, 'Leaded solder contains lead: do not eat, drink or touch your face while soldering, and wash your hands thoroughly afterwards. Prefer lead-free solder where the course allows.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('soldering_station', 4, 'Wear safety glasses; molten solder and clipped component leads can spring into the eyes.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('soldering_station', 5, 'Switch off and unplug the station when finished, and let the iron cool before storing it or changing the tip.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('soldering_station', 6, 'Never solder on a circuit that is powered or connected to a power source.');
