insert into public.equipment (id, name, category, summary, overview, model_asset, default_camera_orbit, model_credit, layout, published)
values ('lcr_meter', 'LCR Meter', 'Measurement', 'Instrument that measures inductance, capacitance and resistance, plus quality factor and dissipation factor.', 'An LCR meter measures the impedance of a component by applying a small AC test signal at a chosen frequency and measuring the voltage and current. From this it calculates inductance (L), capacitance (C) and resistance (R), along with D (dissipation factor), Q (quality factor), ESR and phase angle. A handheld meter has an LCD, a few keys and a test socket or test leads. Components must be removed from live circuits and capacitors discharged before measuring. Based on DER EE DE-5000.', 'models/lcr_meter.glb', '0deg 75deg 0.5m', null, '{"units":"m","body":{"width":0.09,"height":0.19,"depth":0.04,"cornerRadius":0.008,"color":"#3A4A5C"},"parts":[{"id":"lcd_display","type":"screen","face":"front","position":[0,0.062],"size":[0.07,0.045,0.003],"color":"#9FB3A5"},{"id":"power_button","type":"button","face":"front","position":[-0.027,0.02],"size":[0.02,0.012,0.004],"color":"#B04040"},{"id":"hold_button","type":"button","face":"front","position":[0,0.02],"size":[0.02,0.012,0.004],"color":"#8C8B87"},{"id":"freq_button","type":"button","face":"front","position":[0.027,0.02],"size":[0.02,0.012,0.004],"color":"#8C8B87"},{"id":"lcr_button","type":"button","face":"front","position":[-0.027,-0.008],"size":[0.02,0.012,0.004],"color":"#C9A64B"},{"id":"dcr_button","type":"button","face":"front","position":[0,-0.008],"size":[0.02,0.012,0.004],"color":"#8C8B87"},{"id":"ser_par_button","type":"button","face":"front","position":[0.027,-0.008],"size":[0.02,0.012,0.004],"color":"#8C8B87"},{"id":"test_socket","type":"port","face":"top","position":[0,0],"size":[0.03,0.012,0.015],"color":"#1E1E1E"},{"id":"test_leads","type":"probe","face":"right","position":[0,-0.04],"size":[0.008,0.008,0.045],"color":"#A34A4A"},{"id":"battery_cover","type":"handle","face":"back","position":[0,-0.02],"size":[0.05,0.06,0.003],"color":"#2B3A4A"}]}'::jsonb, true)
on conflict (id) do update set name = excluded.name, category = excluded.category, summary = excluded.summary,
  overview = excluded.overview, model_asset = excluded.model_asset, default_camera_orbit = excluded.default_camera_orbit,
  model_credit = excluded.model_credit, layout = excluded.layout, published = true;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('lcr_meter', 'lcd_display', 1, 'LCD Display', 'Shows the primary reading (L, C, R or Z) and a secondary reading (D, Q, ESR or phase angle), together with the unit, test frequency, series or parallel mode and status symbols.', 'Read the value together with the unit prefix (for example nF or mH) and the symbols for the equivalent circuit and frequency. A very large or unstable value can mean the component is not connected.', array['A low-battery symbol means readings may be wrong; replace the battery before relying on measurements.']::text[], 'lcd_display')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('lcr_meter', 'power_button', 2, 'Power Button', 'Switches the meter on and off.', 'Press to switch on and, usually, to switch off. Most meters also turn off automatically after a period without key presses.', array['Switch the meter off before opening the battery cover.']::text[], 'power_button')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('lcr_meter', 'lcr_button', 3, 'LCR / Auto Button', 'Selects the measured quantity: automatic recognition of L, C or R, or a fixed inductance, capacitance or resistance mode.', 'Press to cycle through the modes. Auto mode picks the likely quantity but can be wrong for unusual parts, so choose the mode manually if the result looks odd.', array['Check the mode symbol on the display before you record a reading.']::text[], 'lcr_button')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('lcr_meter', 'dcr_button', 4, 'DCR Button', 'Measures the DC resistance of the component, as opposed to its AC impedance. It is useful for inductor windings.', 'Press DCR, connect an inductor or resistor and read the resistance. Compare to the datasheet DC resistance value.', array['Use DCR only on components that are not connected to a power source.']::text[], 'dcr_button')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('lcr_meter', 'freq_button', 5, 'FREQ Button', 'Changes the test frequency, for example between 100 Hz, 120 Hz, 1 kHz, 10 kHz and 100 kHz, depending on the model.', 'Press FREQ to step through the available frequencies. Use a frequency close to the one the component operates at, as capacitance and inductance values vary with frequency.', array['Do not compare readings taken at different frequencies without noting the frequency used.']::text[], 'freq_button')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('lcr_meter', 'ser_par_button', 6, 'SER / PAR Button', 'Selects the series or parallel equivalent circuit model used to calculate the displayed value.', 'Use the series model for low-impedance parts such as large capacitors and small inductors, and the parallel model for high-impedance parts such as small capacitors and large inductors, or use the automatic setting.', array['Record which model was used when writing down a measurement.']::text[], 'ser_par_button')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('lcr_meter', 'hold_button', 7, 'HOLD Button', 'Freezes the displayed reading so it can be read after the component is removed.', 'Press HOLD to freeze the display and press again to release. The HOLD symbol shows while it is active.', array['Release HOLD before the next measurement; a frozen reading does not update.']::text[], 'hold_button')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('lcr_meter', 'test_socket', 8, 'Test Socket', 'Input connection for the test fixture or leads. Components are placed in the fixture or clipped to the leads so the meter can drive and measure them.', 'Plug in the fixture or leads firmly before switching on. Insert the component leads into the fixture, or clip the leads across the component.', array['Never apply an external voltage to the test socket.', 'Discharge capacitors fully before connecting them to the meter.']::text[], 'test_socket')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('lcr_meter', 'test_leads', 9, 'Test Leads / Clips', 'Lead set with clips or tweezers for measuring components that do not fit the socket or fixture, including surface-mount parts.', 'Short the clips together and use the meter''s zero or open/short calibration function if it has one, then clip across the component. Keep the leads short and still during a measurement.', array['Do not clip the leads on a live circuit.', 'Replace leads that have cracked insulation or loose clips.']::text[], 'test_leads')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('lcr_meter', 'battery_cover', 10, 'Battery Cover', 'Covers the compartment that holds the battery which powers the meter. Some models can also run from a DC adapter.', 'Open the cover with the meter off and the leads removed, replace the battery with the correct type and polarity, and close the cover.', array['Remove the leads and switch off before opening the battery compartment.', 'Do not leave flat batteries in the meter for long; they can leak.']::text[], 'battery_cover')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
delete from public.parts where equipment_id = 'lcr_meter' and id not in ('lcd_display', 'power_button', 'lcr_button', 'dcr_button', 'freq_button', 'ser_par_button', 'hold_button', 'test_socket', 'test_leads', 'battery_cover');
delete from public.safety_rules where equipment_id = 'lcr_meter';
insert into public.safety_rules (equipment_id, sort_order, text) values ('lcr_meter', 1, 'Measure components only when they are removed from the circuit and the circuit is powered off.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('lcr_meter', 2, 'Discharge every capacitor, especially large electrolytic and high-voltage types, before connecting it to the meter. A charged capacitor can damage the meter and give you a shock.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('lcr_meter', 3, 'Never apply external voltage to the meter''s test terminals.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('lcr_meter', 4, 'Do not touch the component leads with your fingers while measuring small values, since body capacitance disturbs the reading.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('lcr_meter', 5, 'Check the battery state and inspect the leads for damage before use.');
