insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q1', 1, 'What does an LCR meter measure?', array['Light, current and resistance', 'Inductance, capacitance and resistance', 'Voltage only', 'Frequency only']::text[], 1, 'L is inductance, C is capacitance and R is resistance.' from public.quizzes where equipment_id = 'lcr_meter' and slug = 'lcr_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q2', 2, 'What must you do to a capacitor before connecting it to the meter?', array['Discharge it fully', 'Charge it fully', 'Heat it', 'Nothing']::text[], 0, 'A charged capacitor can damage the meter and give a shock hazard. Discharge it first.' from public.quizzes where equipment_id = 'lcr_meter' and slug = 'lcr_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q3', 3, 'Can an LCR meter be used on a powered circuit?', array['Yes, always', 'Only for resistors', 'Only at 1 kHz', 'No, components must be unpowered and out of circuit']::text[], 3, 'The meter supplies its own test signal. External voltage or parallel parts give wrong readings or damage it.' from public.quizzes where equipment_id = 'lcr_meter' and slug = 'lcr_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q4', 4, 'What does the D (dissipation factor) value indicate?', array['The part''s colour', 'The part''s size', 'The ratio of energy lost to energy stored, i.e. how lossy the component is', 'The supply voltage']::text[], 2, 'D is the ratio of the resistive to the reactive part of the impedance. Lower D means a better, lower-loss component.' from public.quizzes where equipment_id = 'lcr_meter' and slug = 'lcr_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q5', 5, 'Q (quality factor) is the reciprocal of which value?', array['L', 'D', 'C', 'R']::text[], 1, 'Q = 1/D. It is usually quoted for inductors, while D is usually quoted for capacitors.' from public.quizzes where equipment_id = 'lcr_meter' and slug = 'lcr_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q6', 6, 'Why does test frequency matter?', array['Component values and losses change with frequency', 'It changes the screen brightness', 'It sets the battery life', 'It does not matter']::text[], 0, 'Capacitors and inductors are specified at particular frequencies and real values vary with frequency.' from public.quizzes where equipment_id = 'lcr_meter' and slug = 'lcr_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q7', 7, 'Which equivalent model is normally better for a small, high-impedance capacitor?', array['Series', 'Neither', 'Either gives the same result at all values', 'Parallel']::text[], 3, 'High-impedance parts are better described by the parallel model; low-impedance parts by the series model.' from public.quizzes where equipment_id = 'lcr_meter' and slug = 'lcr_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q8', 8, 'Why should your fingers not touch the leads when measuring a few picofarads?', array['It is unsafe', 'It wears the leads', 'Body capacitance adds to the reading', 'It stops the display']::text[], 2, 'Your body and nearby objects add stray capacitance that matters for very small values.' from public.quizzes where equipment_id = 'lcr_meter' and slug = 'lcr_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q9', 9, 'What is the DCR function used for?', array['Measuring dielectric constant', 'Measuring a component''s DC resistance, such as an inductor winding', 'Setting the display contrast', 'Charging a capacitor']::text[], 1, 'DCR measures the DC resistance of a winding or resistor, which is separate from its AC impedance.' from public.quizzes where equipment_id = 'lcr_meter' and slug = 'lcr_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q10', 10, 'What is the purpose of the open/short calibration, where the meter offers it?', array['To remove the effect of lead and fixture stray impedance', 'To charge the battery', 'To increase the frequency', 'To reset the buttons']::text[], 0, 'Calibrating with the leads open and then shorted compensates for the fixture and lead errors, improving accuracy for small values.' from public.quizzes where equipment_id = 'lcr_meter' and slug = 'lcr_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
delete from public.quiz_questions where quiz_id = (select id from public.quizzes where equipment_id = 'lcr_meter' and slug = 'lcr_basics') and slug not in ('q1', 'q2', 'q3', 'q4', 'q5', 'q6', 'q7', 'q8', 'q9', 'q10');
delete from public.quizzes where equipment_id = 'lcr_meter' and slug not in ('lcr_basics');

-- ===== insulation_tester =====
insert into public.equipment (id, name, category, summary, overview, model_asset, default_camera_orbit, model_credit, layout, published)
values ('insulation_tester', 'Insulation Tester', 'Measurement', 'High-voltage tester that measures insulation resistance in megohms and checks low-resistance continuity.', 'An insulation tester (megohmmeter) applies a high DC test voltage, typically 250 V, 500 V or 1000 V, between a conductor and earth and measures the tiny leakage current to find the insulation resistance, shown in megohms. It is used to check cables, motors and electrical equipment for deterioration before they are energized. Most testers also have a low-voltage continuity function. The test voltage is hazardous, so the circuit must be dead and isolated before testing. Based on Kyoritsu 3005A.', 'models/insulation_tester.glb', '0deg 75deg 0.5m', null, '{"units":"m","body":{"width":0.105,"height":0.16,"depth":0.07,"cornerRadius":0.008,"color":"#E0A526"},"parts":[{"id":"lcd_display","type":"screen","face":"front","position":[0,0.045],"size":[0.08,0.045,0.003],"color":"#9FB3A5"},{"id":"range_selector","type":"knob","face":"front","position":[0,-0.003],"size":[0.045,0.045,0.012],"color":"#2B2B2B"},{"id":"live_circuit_indicator","type":"led","face":"front","position":[-0.04,0],"size":[0.008,0.008,0.003],"color":"#D03030"},{"id":"test_button","type":"button","face":"front","position":[0.03,-0.052],"size":[0.03,0.03,0.008],"color":"#C03030"},{"id":"earth_terminal","type":"port","face":"front","position":[-0.04,-0.052],"size":[0.014,0.014,0.01],"color":"#1E1E1E"},{"id":"line_terminal","type":"port","face":"front","position":[-0.01,-0.052],"size":[0.014,0.014,0.01],"color":"#8A1E1E"},{"id":"red_probe","type":"probe","face":"right","position":[0,0],"size":[0.008,0.008,0.045],"color":"#A34A4A"},{"id":"black_clip","type":"probe","face":"left","position":[0,0],"size":[0.008,0.008,0.045],"color":"#2B2B2B"},{"id":"rubber_holster","type":"handle","face":"back","position":[0,0],"size":[0.085,0.14,0.003],"color":"#2B2B2B"}]}'::jsonb, true)
on conflict (id) do update set name = excluded.name, category = excluded.category, summary = excluded.summary,
  overview = excluded.overview, model_asset = excluded.model_asset, default_camera_orbit = excluded.default_camera_orbit,
  model_credit = excluded.model_credit, layout = excluded.layout, published = true;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('insulation_tester', 'lcd_display', 1, 'LCD Display', 'Shows the insulation resistance in megohms or the continuity resistance in ohms, plus a bar graph, the test voltage and warning symbols.', 'Read the value and unit while the test button is held. Wait for the reading to settle before you record it. An over-range indication means the insulation is better than the selected range can show.', array['The display can show a high-voltage symbol while the test is running; keep your hands off the leads and the circuit.']::text[], 'lcd_display')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('insulation_tester', 'range_selector', 2, 'Function / Voltage Selector', 'Rotary switch that selects the test voltage (for example 250 V, 500 V or 1000 V) or the continuity function, and turns the tester off.', 'Choose a test voltage suited to the equipment rating, as set by your procedure, before connecting the leads. Use the lowest suitable voltage first when you are unsure.', array['Never change the selector while the test button is pressed or while the leads are connected to a circuit.', 'Choose a test voltage not higher than the rating of the equipment''s insulation.']::text[], 'range_selector')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('insulation_tester', 'test_button', 3, 'Test Button', 'Starts the insulation test and applies the test voltage while pressed. Some models have a lock position to hold the test.', 'Press and hold the button after the leads are connected and the circuit has been confirmed dead. Release it when the reading has stabilised.', array['Do not press the test button while touching the leads or the circuit under test.', 'After release, wait for the discharge to finish before touching the circuit.']::text[], 'test_button')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('insulation_tester', 'live_circuit_indicator', 4, 'Live Circuit Warning', 'Warns, with a symbol or light and a buzzer, if the circuit being tested carries a voltage, and later shows the stored charge after the test.', 'Check that the warning is off before starting a test. After a test, wait until the warning goes out to confirm the circuit has discharged.', array['If the warning appears before the test, do not press the test button; the circuit is live.', 'This warning does not replace verifying that the circuit is dead with a proper voltage tester.']::text[], 'live_circuit_indicator')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('insulation_tester', 'line_terminal', 5, 'LINE Terminal', 'Positive output terminal for the red test lead, which carries the test voltage to the conductor under test.', 'Insert the red lead fully into the LINE terminal and connect the other end to the conductor being tested.', array['Only use leads rated for the tester''s voltage and category.', 'Treat the red lead as live whenever the test button is pressed.']::text[], 'line_terminal')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('insulation_tester', 'earth_terminal', 6, 'EARTH Terminal', 'Return terminal for the black lead, usually connected to earth, the metal frame or the other conductor under test.', 'Insert the black lead fully into the EARTH terminal and clip it to the earth or frame connection.', array['Connect the earth clip first and the line lead second, and disconnect in reverse order after the circuit has discharged.']::text[], 'earth_terminal')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('insulation_tester', 'red_probe', 7, 'Red Test Probe', 'Insulated lead with a probe tip (often with a remote test switch) that carries the high test voltage to the conductor.', 'Touch or clip the probe to the conductor under test and hold it steady while testing. Keep your fingers behind the finger guard.', array['Never touch the probe tip during a test.', 'Check the lead insulation for cracks before every use.']::text[], 'red_probe')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('insulation_tester', 'black_clip', 8, 'Black Earth Clip', 'Insulated lead with a clip that connects the EARTH terminal to the earth or the second conductor under test.', 'Clip securely to a clean bare metal point such as the equipment frame or an earth terminal.', array['Make sure the clip cannot slip off during the test.']::text[], 'black_clip')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('insulation_tester', 'rubber_holster', 9, 'Protective Holster', 'Rubber case that protects the tester from knocks and helps with grip. It may carry a strap so the tester can be operated with both hands.', 'Keep the holster on during use and use the strap or stand so that the tester is stable while testing.', array['Do not use the tester if the case or holster is cracked or the terminals are damaged.']::text[], 'rubber_holster')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
delete from public.parts where equipment_id = 'insulation_tester' and id not in ('lcd_display', 'range_selector', 'test_button', 'live_circuit_indicator', 'line_terminal', 'earth_terminal', 'red_probe', 'black_clip', 'rubber_holster');
delete from public.safety_rules where equipment_id = 'insulation_tester';
insert into public.safety_rules (equipment_id, sort_order, text) values ('insulation_tester', 1, 'Confirm the circuit or equipment is dead and isolated with a proper voltage tester before connecting an insulation tester. Prove the voltage tester on a known live source before and after.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('insulation_tester', 2, 'Never touch the leads, probes or circuit while the test button is pressed; the test voltage can be 500 V or 1000 V DC and can cause a painful or dangerous shock.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('insulation_tester', 3, 'After the test, wait for the stored charge to discharge (the tester usually discharges the circuit automatically) before disconnecting the leads, and do not touch the conductor until the live circuit warning is off.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('insulation_tester', 4, 'Disconnect or remove sensitive electronics, surge protectors, capacitors and dimmers before testing, as the test voltage can damage them.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('insulation_tester', 5, 'Select the test voltage according to the equipment rating and your teacher''s or the standard''s instruction; do not exceed it.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('insulation_tester', 6, 'Use only the supplied leads and inspect them for damage. Do not use the tester in wet conditions or near flammable gases.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('insulation_tester', 7, 'Warn others and keep them away from the circuit under test, and never work alone on high-voltage tests.');
insert into public.procedures (equipment_id, slug, title, sort_order) values ('insulation_tester', 'measure_insulation_resistance', 'Measure insulation resistance of a cable or motor', 1)
