insert into public.procedure_steps (procedure_id, equipment_id, step_number, text, part_id)
select id, 'insulation_tester', 6, 'Connect the red probe to the conductor under test, and make sure the live circuit warning is off.', 'red_probe' from public.procedures where equipment_id = 'insulation_tester' and slug = 'measure_insulation_resistance';
