insert into public.fault_scenarios (equipment_id, slug, symptom, explanation, sort_order) values ('insulation_tester', 'live_warning_on', 'Before a test, the live circuit warning lights and the buzzer sounds when the leads are connected to the supposedly isolated motor.', 'The warning indicates a voltage on the circuit. Do not test; re-check the isolation and lock-off, and discharge any stored charge, before continuing.', 1)
