insert into public.quizzes (equipment_id, slug, title, time_limit_sec, sort_order) values ('insulation_tester', 'insulation_basics', 'Insulation tester basics', null, 1)
on conflict (equipment_id, slug) do update set title = excluded.title, time_limit_sec = excluded.time_limit_sec, sort_order = excluded.sort_order;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q1', 1, 'What does an insulation tester measure?', array['Current in a live circuit', 'Insulation resistance in megohms', 'Mains frequency', 'Battery capacity']::text[], 1, 'It applies a high DC voltage and calculates the resistance of the insulation from the small leakage current.' from public.quizzes where equipment_id = 'insulation_tester' and slug = 'insulation_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q2', 2, 'What must you confirm before connecting the tester?', array['The circuit is dead and isolated', 'The circuit is live', 'The tester battery is flat', 'The sponge is wet']::text[], 0, 'Testing a live circuit is dangerous and can damage the tester. Isolate and prove the circuit dead first.' from public.quizzes where equipment_id = 'insulation_tester' and slug = 'insulation_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q3', 3, 'When is it safe to touch the leads?', array['While the test button is pressed', 'When the display shows over-range', 'Whenever you wear thin gloves', 'Only after the test has ended and the circuit has discharged']::text[], 3, 'The test voltage can be up to 1000 V DC and the circuit may hold charge afterwards.' from public.quizzes where equipment_id = 'insulation_tester' and slug = 'insulation_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q4', 4, 'Which test voltage is commonly used for 230 V mains cabling, if your procedure says so?', array['5 V', '10 kV', '500 V DC', '1 V']::text[], 2, '500 V DC is the usual choice for circuits up to 500 V; always follow the standard or instruction in use.' from public.quizzes where equipment_id = 'insulation_tester' and slug = 'insulation_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q5', 5, 'What does a very low reading (for example below 1 megohm) usually mean?', array['The insulation is excellent', 'The insulation is damaged, damp or contaminated', 'The tester is on AC', 'The leads are too long']::text[], 1, 'Low insulation resistance means leakage. The equipment should not be put into service until it is investigated.' from public.quizzes where equipment_id = 'insulation_tester' and slug = 'insulation_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q6', 6, 'Why should electronics be disconnected before an insulation test?', array['The high test voltage can destroy them', 'They would add resistance', 'They interfere with the display', 'They are not needed']::text[], 0, 'Electronic devices, surge arresters and capacitors are not rated for the test voltage.' from public.quizzes where equipment_id = 'insulation_tester' and slug = 'insulation_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q7', 7, 'What does the live circuit warning on the tester tell you?', array['The tester is working', 'The battery is full', 'The leads are plugged in', 'A voltage is present on the circuit being tested']::text[], 3, 'If it shows, do not test. It also shows stored charge after a test.' from public.quizzes where equipment_id = 'insulation_tester' and slug = 'insulation_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q8', 8, 'After releasing the test button, what should you do?', array['Immediately touch the conductor', 'Press the button again', 'Wait until the circuit has discharged before disconnecting', 'Turn the selector to the highest voltage']::text[], 2, 'Capacitive circuits hold a charge. The tester discharges it, and the warning goes off when it is safe.' from public.quizzes where equipment_id = 'insulation_tester' and slug = 'insulation_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q9', 9, 'Why does the reading sometimes rise slowly during a test?', array['The leads are overheating', 'Capacitance charging and dielectric absorption', 'A mains supply is connected', 'The battery is recharging']::text[], 1, 'Insulation resistance readings rise as the cable charges and the insulation polarizes, so a fixed test time is used.' from public.quizzes where equipment_id = 'insulation_tester' and slug = 'insulation_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, slug, sort_order, prompt, options, correct_index, explanation)
select id, 'q10', 10, 'Which statement about changing the selector is correct?', array['Never change it while the test is running or while connected to a circuit', 'Change it while the test button is pressed', 'Always set the highest voltage first', 'It only matters for continuity']::text[], 0, 'Change the selector only when the test is off and the leads are safely disconnected.' from public.quizzes where equipment_id = 'insulation_tester' and slug = 'insulation_basics'
on conflict (quiz_id, slug) do update set sort_order = excluded.sort_order, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;
