delete from public.quizzes where equipment_id = 'insulation_tester' and slug not in ('insulation_basics');

-- ===== breadboard_trainer =====
insert into public.equipment (id, name, category, summary, overview, model_asset, default_camera_orbit, model_credit, layout, published)
values ('breadboard_trainer', 'Breadboard / Digital Trainer', 'Training', 'Bench trainer with solderless breadboard, 5 V supply, logic switches, LEDs, display and clock for building digital circuits.', 'A digital trainer is a bench board for building and testing logic circuits without soldering. It combines a solderless breadboard with a regulated 5 V supply, logic switches for inputs, LEDs and a seven-segment display for outputs, and a clock and pulse source. Students plug ICs and jumper wires into the breadboard and connect them to the trainer''s switches, LEDs and clock. Always switch the supply off before changing wiring and check the power connections of every IC. Based on a typical digital logic trainer such as the Global Specialties PB-505A.', 'models/breadboard_trainer.glb', '0deg 50deg 0.65m', null, '{"units":"m","body":{"width":0.3,"height":0.04,"depth":0.2,"cornerRadius":0.008,"color":"#3B4A3F"},"parts":[{"id":"solderless_breadboard","type":"slot","face":"top","position":[-0.025,0.05],"size":[0.2,0.07,0.008],"color":"#F2F0EA"},{"id":"power_terminals","type":"port","face":"top","position":[0.115,0.06],"size":[0.05,0.04,0.012],"color":"#C9A64B"},{"id":"power_switch","type":"switch","face":"top","position":[0.115,0.02],"size":[0.02,0.02,0.01],"color":"#8C8B87"},{"id":"power_led","type":"led","face":"top","position":[0.115,-0.003],"size":[0.008,0.008,0.003],"color":"#D03030"},{"id":"seven_segment_display","type":"display","face":"top","position":[-0.1,-0.01],"size":[0.04,0.025,0.004],"color":"#C0392B"},{"id":"clock_selector","type":"knob","face":"top","position":[-0.03,-0.01],"size":[0.02,0.02,0.015],"color":"#2B2B2B"},{"id":"pulse_button","type":"button","face":"top","position":[0.005,-0.01],"size":[0.016,0.016,0.006],"color":"#C03030"},{"id":"clock_output_jack","type":"port","face":"top","position":[0.05,-0.01],"size":[0.02,0.012,0.008],"color":"#1E1E1E"},{"id":"led_indicators","type":"led","face":"top","position":[-0.075,-0.035],"size":[0.12,0.012,0.004],"color":"#D8A030"},{"id":"logic_switches","type":"switch","face":"top","position":[-0.075,-0.07],"size":[0.12,0.025,0.012],"color":"#E9E9E7"}]}'::jsonb, true)
on conflict (id) do update set name = excluded.name, category = excluded.category, summary = excluded.summary,
  overview = excluded.overview, model_asset = excluded.model_asset, default_camera_orbit = excluded.default_camera_orbit,
  model_credit = excluded.model_credit, layout = excluded.layout, published = true;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('breadboard_trainer', 'solderless_breadboard', 1, 'Solderless Breadboard', 'A grid of spring-clip sockets in which ICs, resistors and jumper wires are plugged to build circuits without soldering. Short rows of five holes are connected, and long power rails run along the edges.', 'Place ICs across the centre gap so each pin has its own row. Connect wires between rows to form the circuit. Connect the power rails to the trainer''s supply and then to each IC''s power pins.', array['Do not push thick or damaged leads into the sockets, as they can damage the contacts.', 'Wire the circuit with the power switched off.']::text[], 'solderless_breadboard')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('breadboard_trainer', 'power_terminals', 2, 'Power Supply Terminals', 'Binding posts or jacks that provide the regulated +5 V (and ground) supply for TTL logic, and on some trainers extra voltages.', 'Use short wires from the +5 V and ground posts to the breadboard rails. Check the polarity before switching on.', array['Never connect +5 V directly to ground; this is a short circuit.', 'Do not connect an external supply to these posts.']::text[], 'power_terminals')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('breadboard_trainer', 'power_switch', 3, 'Power Switch', 'Turns the trainer''s supply on and off.', 'Switch on only after the wiring has been checked. Switch off before changing connections or inserting and removing ICs.', array['Switch the trainer off before changing wires or ICs.', 'Do not exceed the supply''s rated current.']::text[], 'power_switch')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('breadboard_trainer', 'power_led', 4, 'Power Indicator LED', 'Shows that the trainer is switched on and the supply is present.', 'Check that it lights when the power is on. If it does not, check the mains connection and the fuse.', array['If an IC becomes hot, switch off immediately and check the wiring.']::text[], 'power_led')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('breadboard_trainer', 'logic_switches', 5, 'Logic Switches', 'A row of toggle (data) switches that give a logic 1 (+5 V) or logic 0 (ground) to the circuit inputs.', 'Wire a switch output to an IC input. Set the switch up for logic 1 and down for logic 0 and watch the LED outputs.', array['Do not connect a switch output to an IC output; this can damage both.']::text[], 'logic_switches')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('breadboard_trainer', 'led_indicators', 6, 'LED Indicators', 'A row of LEDs with series resistors that show the logic level of the connected signals. Lit means logic 1.', 'Connect an IC output to an LED input and read the state. An LED may stay dim or off if the output is floating.', array['Do not connect an LED directly across the supply without its series resistor.']::text[], 'led_indicators')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('breadboard_trainer', 'seven_segment_display', 7, 'Seven-Segment Display', 'A display of seven LED segments that shows decimal digits, usually driven through a BCD to seven-segment decoder IC.', 'Feed the four BCD bits from a counter or switches to the decoder inputs and the decoder outputs to the display, as in the trainer''s labelling.', array['Use current-limiting resistors on directly driven segments.']::text[], 'seven_segment_display')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('breadboard_trainer', 'clock_selector', 8, 'Clock Selector', 'Selects the frequency of the clock generator, for example 1 Hz, 1 kHz or 10 kHz, or adjusts the speed.', 'Choose a slow clock (1 Hz) to watch a counter count on the LEDs, and a faster clock for oscilloscope measurements.', array['Rapid flashing LEDs at a high clock rate can bother photosensitive people; use a slow clock for demonstrations.']::text[], 'clock_selector')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('breadboard_trainer', 'pulse_button', 9, 'Debounced Pulse Button', 'A pushbutton whose output is cleaned by a debounce circuit, giving one clean pulse per press. It is used for single-stepping a counter or flip-flop.', 'Connect the pulser output to a clock input, then press to advance the circuit by one step.', array['Use the debounced pulser, not a raw switch, as the clock for counters, since contact bounce causes extra counts.']::text[], 'pulse_button')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
insert into public.parts (equipment_id, id, number, name, function, usage, safety, node_name)
values ('breadboard_trainer', 'clock_output_jack', 10, 'Clock Output Jack', 'Output terminal that provides the TTL clock signal selected by the clock selector.', 'Connect a wire from this jack to the clock input of the IC under test, or to an oscilloscope probe to view the clock.', array['Do not connect this output to the supply or to another IC output.']::text[], 'clock_output_jack')
on conflict (equipment_id, id) do update set number = excluded.number, name = excluded.name, function = excluded.function,
  usage = excluded.usage, safety = excluded.safety, node_name = excluded.node_name;
delete from public.parts where equipment_id = 'breadboard_trainer' and id not in ('solderless_breadboard', 'power_terminals', 'power_switch', 'power_led', 'logic_switches', 'led_indicators', 'seven_segment_display', 'clock_selector', 'pulse_button', 'clock_output_jack');
delete from public.safety_rules where equipment_id = 'breadboard_trainer';
insert into public.safety_rules (equipment_id, sort_order, text) values ('breadboard_trainer', 1, 'Switch the trainer off before inserting or removing ICs or changing any wiring.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('breadboard_trainer', 2, 'Check the power connections of every IC (Vcc to +5 V, GND to ground) before switching on. Wrong supply wiring can destroy ICs and make them hot.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('breadboard_trainer', 3, 'Never connect two IC outputs together, and never connect an output directly to the supply or ground.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('breadboard_trainer', 4, 'Use only TTL-level signals and the trainer''s 5 V rail for TTL ICs. Do not apply more than the rated voltage.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('breadboard_trainer', 5, 'Handle ICs by the body, avoid touching the pins with your hands, and keep them away from static electricity, as CMOS parts are static sensitive.');
insert into public.safety_rules (equipment_id, sort_order, text) values ('breadboard_trainer', 6, 'Keep liquids away from the trainer and disconnect it from the mains before opening it.');
